update_section_html() {
    local start_comment="$1"
    local end_comment="$2"
    local content_file="$3"

    sed -i "/$start_comment/,/$end_comment/{
        /$start_comment/!{/$end_comment/!d}
        /$start_comment/r $content_file
    }" "$INDEX_FILE"
}

