def list_png_files():
    png_files = [f for f in os.listdir('banners') if f.endswith('.png')]
    if not png_files:
        print_error("No PNG files found in the 'banners' directory.")
        sys.exit(1)

    selected_image = random.choice(png_files)
    return os.path.join('banners', selected_image)

def main():

    rows, columns = get_terminal_size()
    if rows and columns:
        #Make responsive image ;) feel like frontend

        image_res = int(columns)
    else:
        image_res = 50

    if '-i' in sys.argv or '--image' in sys.argv:
        try:
            if '-i' in sys.argv:
                image_path = sys.argv[sys.argv.index('-i') + 1]
            else:
                image_path = sys.argv[sys.argv.index('--image') + 1]
        except IndexError:
            print_error("Error: No image path provided after the flag.")
            sys.exit(1)
    elif '-h' in sys.argv or '--half' in sys.argv:
        image_res = 50
    else:

        image_path = list_png_files()

    if not os.path.isfile(image_path):
        print_error(f"Error: The file '{image_path}' does not exist.")
        sys.exit(1)

    image_to_bash(image_path, image_res)

if __name__ == "__main__":

    main()

log() {
    local level="$1"
    shift
    local text="$*"
    local prefix
    case "$level" in
        INFO) prefix="${C_CYAN}[*]${C_RESET}" ;;
        OK) prefix="${C_GREEN}[+]${C_RESET}" ;;
        WARN) prefix="${C_YELLOW}[!]${C_RESET}" ;;
        ERROR) prefix="${C_RED}[ERROR]${C_RESET}" ;;
    esac
    if [[ "$level" == "WARN" || "$level" == "ERROR" ]]; then
        printf '%b %s\n' "$prefix" "$text" >&2
    else
        printf '%b %s\n' "$prefix" "$text"
    fi
}

fail() {
    log ERROR "$1" >&2
    exit 1
}

clone_fresh() {
    spin_run "Cloning LazyOwn ($LAZYOWN_BRANCH) into $LAZYOWN_DIR" \
        git clone --branch "$LAZYOWN_BRANCH" --depth 1 "$LAZYOWN_REPO" "$LAZYOWN_DIR" \
        || fail "Clone failed. Check the URL and your network connection."
}

clean_checkout() {
    backup_payload
    log WARN "Removing everything in $LAZYOWN_DIR"
    rm -rf "$LAZYOWN_DIR"
    clone_fresh
}

ask_existing_checkout_action() {
    local answer=""
    printf "\n${C_BOLD}${C_CYAN}Existing installation detected at $LAZYOWN_DIR (branch $LAZYOWN_BRANCH).${C_RESET}\n"
    echo "How do you want to proceed?"
    echo "  [1] Update in place (git pull + reinstall over it)"
    echo "  [2] Clean install (delete everything and clone fresh)"
    echo "  [3] Install into a different directory"
    echo "  [4] Abort installation"
    while true; do
        ask "Select [1/2/3/4] (default 1): "
        answer="${ASK_ANSWER:-1}"
        case "$answer" in
            1 | update) echo "update"; return 0 ;;
            2 | clean) echo "clean"; return 0 ;;
            3 | newdir) echo "newdir"; return 0 ;;
            4 | abort) echo "abort"; return 0 ;;
            *) echo "Please answer 1, 2, 3 or 4." ;;
        esac
    done
}

ask_existing_path_action() {
    local answer=""
    printf "\n${C_BOLD}${C_YELLOW}Path $LAZYOWN_DIR exists and is not a LazyOwn checkout.${C_RESET}\n"
    echo "How do you want to proceed?"
    echo "  [1] Install into a different directory (default)"
    echo "  [2] Delete it and install here (requires confirmation)"
    echo "  [3] Abort installation"
    while true; do
        ask "Select [1/2/3] (default 1): "
        answer="${ASK_ANSWER:-1}"
        case "$answer" in
            1 | newdir) echo "newdir"; return 0 ;;
            2 | delete) echo "delete"; return 0 ;;
            3 | abort) echo "abort"; return 0 ;;
            *) echo "Please answer 1, 2 or 3." ;;
        esac
    done
}

def __getitem__(self, key: str) -> str:
    if key not in self:
        return ""
    value = super().__getitem__(key)
    return "" if value is None else str(value)

def _substitute(template: str, payload: dict[str, Any]) -> str:
    """Render ``template`` against ``payload`` placeholders.

    Falls back to the literal template if ``str.format_map`` raises
    (e.g. unbalanced braces from legacy strings) so a malformed entry
    cannot prevent the shell from booting.
    """
    safe = _SafeFormatDict(payload)
    try:
        return template.format_map(safe)
    except (IndexError, ValueError):
        return template

def template_placeholders(template: str) -> set[str]:
    """Return the ``{name}`` placeholders referenced by ``template``.

    Malformed templates (unbalanced braces from legacy strings) yield an
    empty set — the same fail-safe spirit as :func:`_substitute`.
    """
    names: set[str] = set()
    try:
        for _, field_name, _, _ in string.Formatter().parse(template):
            if field_name:
                names.add(field_name.split(".")[0].split("[")[0])
    except ValueError:
        return set()
    return names

def empty_placeholders(template: str, context: dict[str, Any]) -> list[str]:
    """Return placeholders whose rendered value against ``context`` is empty."""
    return sorted(name for name in template_placeholders(template) if not str(context.get(name) or "").strip())

def __init__(self, config: AutoCryptoConfig | None = None) -> None:
    self._config: AutoCryptoConfig = config or AutoCryptoConfig()
    self._salt_path: Path = Path(self._config.sessions_dir) / SALT_FILE

@property

def enabled(self) -> bool:
    """Whether the engine performs any I/O."""
    return self._config.auto_enabled

@property

def is_encrypted(self) -> bool:
    """Check whether session data appears encrypted.

    Returns True when at least one protected file has the encrypted
    suffix marker applied. A directory with no protected files at all
    returns False (nothing to protect).
    """
    sessions = Path(self._config.sessions_dir)
    if not sessions.exists():
        return False
    for pattern in self._config.protect_globs:
        matches = list(sessions.glob(f"{pattern}{ENCRYPTED_SUFFIX}"))
        if matches:
            return True
    matched_encrypted = False
    for pattern in self._config.protect_globs:
        for path in sessions.glob(pattern):
            try:
                with open(path, "rb") as fh:
                    header = fh.read(32)
            except OSError:
                continue
            if header and (header.startswith(b"gAAAAA") or header[:4] == b"\x80\x00\x00\x00"):
                matched_encrypted = True
                break
        if matched_encrypted:
            break
    return matched_encrypted

def decrypt_session(self) -> bool:
    """Decrypt all protected session files.

    Returns True when at least one file was decrypted, False when no
    encrypted files exist or the password is wrong/absent.
    """
    if not self._config.auto_enabled:
        return False
    password = self._get_password()
    if not password:
        return False

    from cryptography.fernet import Fernet, InvalidToken

    salt = self._load_or_create_salt()
    key = self._derive_key(password, salt)
    cipher = Fernet(key)

    sessions = Path(self._config.sessions_dir)
    if not sessions.exists():
        return False

    decrypted_count = 0
    encrypted_files = list(sessions.glob(f"*{ENCRYPTED_SUFFIX}"))
    if not encrypted_files:
        for pattern in self._config.protect_globs:
            for path in sessions.glob(pattern):
                if not path.is_file():
                    continue
                try:
                    with open(path, "rb") as fh:
                        header = fh.read(8)
                    if header.startswith(b"gAAAAA") or header[:4] == b"\x80\x00\x00\x00":
                        encrypted_files.append(path)
                except OSError:
                    continue

    for path in encrypted_files:
        if path.name == SALT_FILE or path.name == SALT_FILE + ENCRYPTED_SUFFIX:
            continue

def _get_password(self) -> str | None:
    provider = self._config.password_provider
    if provider is None:
        return None
    try:
        return provider()
    except Exception:
        return None

def _load_or_create_salt(self) -> bytes:
    try:
        raw = self._salt_path.read_bytes()
        if len(raw) >= 16:
            return raw[:16]
    except FileNotFoundError:
        pass
    except OSError as exc:
        _log.warning("auto_crypto: cannot read salt: %s", exc)
    salt = secrets.token_bytes(16)
    self._salt_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        fd = os.open(self._salt_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            os.write(fd, salt)
        finally:
            os.close(fd)
        return salt
    except FileExistsError:
        try:
            raw = self._salt_path.read_bytes()
            if len(raw) >= 16:
                return raw[:16]
        except OSError:
            pass
        return salt
    except OSError as exc:
        _log.warning("auto_crypto: cannot write salt: %s", exc)
        return salt

@staticmethod

def _derive_key(password: str, salt: bytes) -> bytes:
    from core.crypto import derive_key

    return derive_key(password, salt)

    def _provider() -> str | None:
        master_pass = os.environ.get("LAZYOWN_MASTER_PASSWORD")
        if master_pass:
            return master_pass
        try:
            from modules.cli_auth import get_current_operator

            username = get_current_operator()
            if username:
                return f"lazyown:{username}"
        except ImportError:
            pass
        return None

    return _provider


