# ── Hot reload (item 7) ──────────────────────────────────────────────────────

class HotReloader(ABC):
    """Notify subscribers when a watched directory changes."""

    @abstractmethod

def stop(self) -> None:
    self._stop.set()
    if self._thread:
        self._thread.join(timeout=2.0)
        self._thread = None

def poll_once(self) -> list[Path]:
    """Run a single scan, fire callbacks for changed paths, return them."""
    current = self._scan()
    changed: list[Path] = []
    for p, mtime in current.items():
        if self._snapshot.get(p) != mtime:
            changed.append(p)
    for p in self._snapshot.keys() - current.keys():
        changed.append(p)
    self._snapshot = current
    for p in changed:
        try:
            self._on_change(p)
        except Exception:
            continue
    return changed

def _loop(self) -> None:
    while not self._stop.is_set():
        self.poll_once()
        self._stop.wait(self._tick)

    def _scan(self) -> dict[Path, float]:
        snap: dict[Path, float] = {}
        for d in self._dirs:
            if not d.exists():
                continue
            for fp in d.rglob("*"):
                if not fp.is_file():
                    continue
                if fp.suffix.lower() not in (".yaml", ".yml", ".lua"):
                    continue
                try:
                    snap[fp] = fp.stat().st_mtime
                except OSError:
                    continue
        return snap


