def _parse_pom_xml(filepath: str) -> list[tuple[str, str]]:
    """Parse a Maven pom.xml file.

    Args:
        filepath: Path to pom.xml.

    Returns:
        List of (artifact_id, version) tuples.
    """
    deps = []
    try:
        from defusedxml import ElementTree as ET

        ns = {"mvn": "http://maven.apache.org/POM/4.0.0"}
        tree = ET.parse(filepath)
        for dep in tree.findall(".//mvn:dependency", ns):
            aid = dep.find("mvn:artifactId", ns)
            ver = dep.find("mvn:version", ns)
            if aid is not None and ver is not None:
                name = aid.text or ""
                version = ver.text or "*"
                if name:
                    deps.append((name, version))
    except Exception:
        pass
    return deps

def _extract_flag(args: list[str], flag: str) -> str | None:
    """Extract a ``--flag <value>`` pair from a list of arguments."""
