@dataclass

def undo(self) -> dict[str, Any] | None:
    """Pop the newest snapshot.

    Returns:
        Previous state or None when the stack is empty.
    """
    if not self._stack:
        return None
    return self._stack.pop()

def depth(self) -> int:
    """Return number of stored undo steps."""
    return len(self._stack)

def get_shell_history(shell: Any) -> ConfigHistory:
    """Return the ConfigHistory bound to a shell, creating it on demand.

    Args:
        shell: Parent shell object used as attribute host.

    Returns:
        The shared ConfigHistory instance.
    """
    existing = getattr(shell, "_config_history", None)
    if isinstance(existing, ConfigHistory):
        return existing
    created = ConfigHistory()
    try:
        object.__setattr__(shell, "_config_history", created)
    except Exception:
        try:
            shell._config_history = created
        except Exception:
            return created
    return created

def _field_status(self, key: str, value: Any) -> tuple[str, str]:
    """Return (status_label, color) for a field value."""
    if value is None:
        return ("NOT SET", "red")
    str_val = str(value).strip()
    if str_val in self._config.null_markers:
        return ("NOT SET", "red")
    if str_val == self._config.default_marker:
        return ("CHANGE ME", "yellow")
    return ("OK", "green")

def render_quick_check(self) -> None:
    """Quick check: show only required fields that are not set."""
    missing: list[str] = []
    for _group_name, fields in FIELD_GROUPS.items():
        for key, (_description, importance, hint) in fields.items():
            if importance == "required":
                value = self._params.get(key)
                status, _ = self._field_status(key, value)
                if status != "OK":
                    missing.append(f"  [red]{key}[/] -- {hint}")

    if missing:
        _console.print(
            Panel(
                "\n".join(missing),
                title="[bold red]Required fields not set[/]",
                border_style="red",
            )
        )
    else:
        _console.print("[green]All required fields are configured.[/]")

