def __init__(self, current_os: str = ANY_OS) -> None:
    """Store the platform used to filter incompatible entries."""

    self.current_os = normalise_os(current_os, default=ANY_OS)

def addons_for_service(
    self,
    service: DiscoveredService,
    addons: Sequence[AddonEntry],
) -> list[AddonEntry]:
    """Return addons whose trigger and OS match the given service."""

    matches: list[AddonEntry] = []
    for addon in addons:
        if not addon.enabled:
            continue
        if not self._os_compatible(addon.addon_os):
            continue
        if self._trigger_matches(addon.trigger, service.service):
            matches.append(addon)
    return matches

def tools_for_service(
    self,
    service: DiscoveredService,
    tools: Sequence[ToolEntry],
) -> list[ToolEntry]:
    """Return active tools whose trigger and OS match the service."""

    matches: list[ToolEntry] = []
    for tool in tools:
        if not tool.active:
            continue
        if not self._os_compatible(tool.tool_os):
            continue
        if self._trigger_matches(tool.trigger, service.service):
            matches.append(tool)
    return matches

def _os_compatible(self, candidate_os: str) -> bool:
    """Return True when ``candidate_os`` is ``any`` or equals current OS."""

    if candidate_os == ANY_OS or self.current_os == ANY_OS:
        return True
    return candidate_os == self.current_os

@staticmethod

def _trigger_matches(trigger: Sequence[str], service_name: str) -> bool:
    """Return True when ``service_name`` is listed in trigger or wildcard."""

    if not trigger:
        return False
    if TRIGGER_WILDCARD in trigger:
        return True
    return service_name in trigger

def __init__(self, config: ExplorationConfig | None = None) -> None:
    """Store the configuration used to locate the transcript file."""

    self.config = config or ExplorationConfig()

def executed_commands(self) -> set[str]:
    """Return the set of unique tool/command names already run."""

    csv_path = Path(self.config.sessions_dir) / self.config.history_csv
    if not csv_path.is_file():
        return set()
    seen: set[str] = set()
    try:
        with csv_path.open(newline="", encoding="utf-8", errors="ignore") as fh:
            reader = csv.DictReader(fh)
            for row in reader:
                for col in self.config.history_command_columns:
                    raw = (row.get(col) or "").strip()
                    if not raw:
                        continue
                    head = raw.split()[0]
                    seen.add(head)
                    seen.add(head.removeprefix("do_"))
                    seen.add(f"do_{head}")
    except OSError:
        return seen
    return seen

def services(self, target: str | None = None) -> list[DiscoveredService]:
    """Return the discovered services for the engagement."""

    return self.nmap_reader.discover(target)

def addons(self) -> list[AddonEntry]:
    """Return the parsed lazyaddon catalogue."""

    return self.addon_catalog.load()

def tools(self) -> list[ToolEntry]:
    """Return the parsed ``.tool`` catalogue."""

    return self.tool_catalog.load()

def history(self) -> set[str]:
    """Return the set of already-executed command names."""

    return self.history_reader.executed_commands()

def unexplored_addons(
    self,
    target: str | None = None,
) -> list[AddonEntry]:
    """Return addons triggered by the scan that have never been run."""

    history = self.history()
    seen_addons: set[str] = set()
    unexplored: list[AddonEntry] = []
    for groups in self.suggestions_for_target(target).values():
        for addon in groups["addons"]:
            if not isinstance(addon, AddonEntry):
                continue
            if addon.name in seen_addons:
                continue
            seen_addons.add(addon.name)
            if addon.name in history:
                continue
            unexplored.append(addon)
    return unexplored

def unexplored_tools(
    self,
    target: str | None = None,
) -> list[ToolEntry]:
    """Return tools triggered by the scan that have never been run."""

    history = self.history()
    seen_tools: set[str] = set()
    unexplored: list[ToolEntry] = []
    for groups in self.suggestions_for_target(target).values():
        for tool in groups["tools"]:
            if not isinstance(tool, ToolEntry):
                continue
            if tool.name in seen_tools:
                continue
            seen_tools.add(tool.name)
            if tool.name in history:
                continue
            unexplored.append(tool)
    return unexplored

def coverage(self, target: str | None = None) -> CoverageReport:
    """Return an aggregate :class:`CoverageReport` for the engagement."""

    services = self.services(target)
    history = self.history()
    addons = self.addons()
    tools = self.tools()

    services_with_command = 0
    addon_executed_names: set[str] = set()
    tool_executed_names: set[str] = set()

    for service in services:
        matching_addons = self.matcher.addons_for_service(service, addons)
        matching_tools = self.matcher.tools_for_service(service, tools)
        any_run = False
        for addon in matching_addons:
            if addon.name in history:
                addon_executed_names.add(addon.name)
                any_run = True
        for tool in matching_tools:
            if tool.name in history:
                tool_executed_names.add(tool.name)
                any_run = True
        if any_run:
            services_with_command += 1

    for addon in addons:
        if addon.name in history:
            addon_executed_names.add(addon.name)
    for tool in tools:
        if tool.name in history:
            tool_executed_names.add(tool.name)

    return CoverageReport(
        services_total=len(services),
        services_with_run_command=services_with_command,
        addons_total=len(addons),
        addons_enabled=sum(1 for a in addons if a.enabled),
        addons_executed=len(addon_executed_names),

def resolve_current_os(payload: Mapping[str, object] | None) -> str:
    """Resolve the current victim platform from a payload-like mapping.

    The lookup honours both the explicit ``platform`` key (new) and the
    legacy numeric ``os_id`` so existing payload.json files keep working.
    Unknown or missing values fall back to :data:`ANY_OS`.
    """

    if not payload:
        return ANY_OS
    explicit = payload.get("platform")
    if isinstance(explicit, str) and explicit.strip().lower() in ALLOWED_OS_VALUES:
        return explicit.strip().lower()
    legacy = payload.get("os_id")
    try:
        legacy_int = int(legacy) if isinstance(legacy, (int, str)) else 0
    except (TypeError, ValueError):
        legacy_int = 0
    return OS_ID_TO_PLATFORM.get(legacy_int, ANY_OS)

def normalise_os(value: object, default: str) -> str:
    """Coerce arbitrary YAML/JSON values to a whitelisted OS string."""

    if not isinstance(value, str):
        return default
    candidate = value.strip().lower()
    if not candidate:
        return default
    if candidate in ALLOWED_OS_VALUES:
        return candidate
    return default

    def from_payload(cls, payload: dict | None) -> PickerConfig:
        """Build a config from a payload.json view, falling back to defaults.

        Honours an optional ``fuzzy_picker`` mapping inside ``payload.json``
        so operators can pin the picker geometry without code changes. Any
        unknown key is ignored.
        """
        if not payload:
            return cls()
        block = payload.get("fuzzy_picker") or {}
        if not isinstance(block, dict):
            return cls()
        valid_fields = {f.name for f in cls.__dataclass_fields__.values()}
        overrides = {k: v for k, v in block.items() if k in valid_fields}
        if not overrides:
            return cls()
        try:
            return cls(**overrides)
        except TypeError:
            return cls()


@dataclass(frozen=True)

def _score(self, haystack: str, query: str) -> tuple[float, tuple[int, ...]]:
    if not haystack:
        return self._cfg.score_zero, ()
    if haystack == query:
        return self._cfg.score_exact, tuple(range(len(query)))
    if haystack.startswith(query):
        return self._cfg.score_prefix, tuple(range(len(query)))
    positions = self._subsequence_positions(haystack, query)
    if positions:
        return self._cfg.score_subsequence, positions
    idx = haystack.find(query)
    if idx >= 0:
        return self._cfg.score_substring, tuple(range(idx, idx + len(query)))
    similarity = SequenceMatcher(None, haystack, query).ratio()
    if similarity >= self._cfg.score_similarity_floor:
        return similarity * self._cfg.score_similarity_weight, ()
    return self._cfg.score_zero, ()

@staticmethod

def _subsequence_positions(haystack: str, query: str) -> tuple[int, ...]:
    positions: list[int] = []
    cursor = 0
    for char in query:
        found = haystack.find(char, cursor)
        if found < 0:
            return ()
        positions.append(found)
        cursor = found + 1
    return tuple(positions)

def __init__(self, config: PickerConfig, scorer: MatchScorer) -> None:
    self._cfg = config
    self._scorer = scorer

def run(self, items: Sequence[PickerItem], initial_query: str) -> str | None:
    if not items:
        return None
    if not self._tty_available():
        return None
    try:
        return curses.wrapper(self._event_loop, list(items), initial_query)
    except curses.error:
        return None
    except KeyboardInterrupt:
        return None

@staticmethod

def _init_colors(self) -> None:
    if not curses.has_colors():
        return
    try:
        curses.start_color()
        curses.use_default_colors()
    except curses.error:
        return
    default_bg = -1
    pairs = (
        (self._cfg.color_pair_border, self._cfg.color_border_fg, default_bg),
        (self._cfg.color_pair_header, self._cfg.color_header_fg, default_bg),
        (self._cfg.color_pair_footer, self._cfg.color_footer_fg, default_bg),
        (self._cfg.color_pair_item, self._cfg.color_item_fg, default_bg),
        (self._cfg.color_pair_selected, self._cfg.color_selected_fg, self._cfg.color_selected_bg),
        (self._cfg.color_pair_highlight, self._cfg.color_highlight_fg, default_bg),
        (self._cfg.color_pair_description, self._cfg.color_description_fg, default_bg),
    )
    for pair_id, fg, bg in pairs:
        try:
            curses.init_pair(pair_id, fg, bg)
        except curses.error:
            continue

def _event_loop(self, stdscr: curses.window, items: list[PickerItem], initial_query: str) -> str | None:
    curses.curs_set(0)
    stdscr.keypad(True)
    self._init_colors()
    query = initial_query or ""
    cursor_index = 0
    scroll_offset = 0
    while True:
        ranked = self._scorer.rank(items, query)
        if not ranked:
            self._render_empty(stdscr, query)
            key = stdscr.getch()
            action = self._classify_key(key)
            if action == "cancel":
                return None
            if action == "select":
                return None
            if action == "backspace" and query:
                query = query[:-1]
            elif action == "char":
                query += chr(key)
            continue
        cursor_index = min(cursor_index, len(ranked) - 1)
        scroll_offset = self._clamp_scroll(scroll_offset, cursor_index, len(ranked))
        self._render(stdscr, ranked, query, cursor_index, scroll_offset)
        key = stdscr.getch()
        action = self._classify_key(key)
        if action == "cancel":
            return None
        if action == "select":
            return ranked[cursor_index].item.text
        if action == "up":
            cursor_index = max(0, cursor_index - 1)
        elif action == "down":
            cursor_index = min(len(ranked) - 1, cursor_index + 1)
        elif action == "page_up":
            cursor_index = max(0, cursor_index - self._vis

def _classify_key(self, key: int) -> str:
    cfg = self._cfg
    if key in (cfg.key_escape, cfg.key_ctrl_c, cfg.key_ctrl_g):
        return "cancel"
    if key in (cfg.key_tab, cfg.key_enter, cfg.key_carriage_return, curses.KEY_ENTER):
        return "select"
    if key == curses.KEY_UP:
        return "up"
    if key == curses.KEY_DOWN:
        return "down"
    if key in (curses.KEY_PPAGE,):
        return "page_up"
    if key in (curses.KEY_NPAGE,):
        return "page_down"
    if key == curses.KEY_HOME:
        return "home"
    if key == curses.KEY_END:
        return "end"
    if key in (curses.KEY_BACKSPACE, 127, 8):
        return "backspace"
    if 32 <= key <= 126:
        return "char"
    return "noop"

def _clamp_scroll(self, offset: int, cursor: int, total: int) -> int:
    visible = self._visible_rows()
    if cursor < offset:
        return cursor
    if cursor >= offset + visible:
        return cursor - visible + 1
    if offset + visible > total:
        return max(0, total - visible)
    return offset

def _draw_box(self, stdscr: curses.window, top: int, left: int, height: int, width: int) -> None:
    attr = self._color(self._cfg.color_pair_border)
    cfg = self._cfg
    horizontal = cfg.glyph_horizontal * (width - 2)
    try:
        stdscr.addnstr(top, left, cfg.glyph_top_left + horizontal + cfg.glyph_top_right, width, attr)
        for y in range(top + 1, top + height - 1):
            stdscr.addnstr(y, left, cfg.glyph_vertical, 1, attr)
            stdscr.addnstr(y, left + width - 1, cfg.glyph_vertical, 1, attr)
        stdscr.addnstr(
            top + height - 1, left, cfg.glyph_bottom_left + horizontal + cfg.glyph_bottom_right, width, attr
        )
    except curses.error:
        pass

def _draw_footer(self, stdscr: curses.window, row_y: int, left: int, width: int) -> None:
    attr = self._color(self._cfg.color_pair_footer)
    try:
        stdscr.addnstr(
            row_y,
            left + self._cfg.box_padding_x + 1,
            self._cfg.footer_help,
            width - 2 - self._cfg.box_padding_x,
            attr,
        )
    except curses.error:
        pass

def _color(self, pair_id: int) -> int:
    if not curses.has_colors():
        return curses.A_NORMAL
    try:
        return curses.color_pair(pair_id)
    except curses.error:
        return curses.A_NORMAL

def __init__(
    self,
    config: PickerConfig | None = None,
    view_factory: Callable[[PickerConfig, MatchScorer], PickerView] | None = None,
) -> None:
    self._cfg = config or PickerConfig()
    self._scorer = MatchScorer(self._cfg)
    factory = view_factory or (lambda cfg, scorer: CursesPickerView(cfg, scorer))
    self._view = factory(self._cfg, self._scorer)

@property

def pick(self, items: Sequence[PickerItem], initial_query: str = "") -> str | None:
    """Return the selected item text or ``None`` on cancel / empty input.

    When there are fewer items than ``activation_threshold`` the picker
    short-circuits to the single value, preserving readline's normal
    single-match auto-insertion semantics for callers that route every
    match through the picker.
    """
    if not items:
        return None
    if len(items) < self._cfg.activation_threshold:
        return items[0].text
    return self._view.run(items, initial_query)

def install(self) -> None:
    """Wire the picker into ``readline.set_completion_display_matches_hook``."""
    try:
        import readline
    except ImportError:
        return
    readline.set_completion_display_matches_hook(self._on_display_matches)

def uninstall(self) -> None:
    """Remove the readline display hook installed by :py:meth:`install`."""
    try:
        import readline
    except ImportError:
        return
    readline.set_completion_display_matches_hook(None)

def _on_display_matches(self, substitution: str, matches: Sequence[str], longest_match_length: int) -> None:
    try:
        import readline
    except ImportError:
        return
    normalised = [self._strip_ansi(m) for m in matches if m]
    if not normalised:
        return
    items = [PickerItem(text=text) for text in normalised]
    chosen = self._picker.pick(items, initial_query=substitution or "")
    if not chosen:
        self._redraw_prompt()
        return
    remainder = chosen[len(substitution) :] if chosen.startswith(substitution) else chosen
    try:
        readline.insert_text(remainder)
        readline.redisplay()
    except Exception:
        self._redraw_prompt()

