    plan: ReconPlan | None,
    plan_path: Path | None,
    clock_fn: Callable[[], float],
) -> bool:
    sessions = Path(cfg.sessions_dir)
    try:
        sessions.mkdir(parents=True, exist_ok=True)
    except OSError:
        return False
    record = {
        "id": uuid.uuid4().hex[:12],
        "ts": clock_fn(),
        "type": cfg.event_kind,
        "severity": cfg.event_severity,
        "payload": {
            "target": target,
            "plan_path": str(plan_path) if plan_path else None,
            "item_count": len(plan.items) if plan is not None else 0,
            "service_count": len(plan.services) if plan is not None else 0,
            "phase": cfg.phase,
        },
    }
    try:
        encoded = json.dumps(record, ensure_ascii=False, default=str) + "\n"
    except (TypeError, ValueError):
        return False
    events_path = sessions / cfg.events_file
    try:
        fd = os.open(
            str(events_path),
            os.O_WRONLY | os.O_CREAT | os.O_APPEND,
            cfg.file_mode,
        )
    except OSError:
        return False
    try:
        os.write(fd, encoded.encode("utf-8"))

def _atomic_write_json(path: Path, data: Mapping[str, Any], mode: int) -> bool:
    try:
        encoded = json.dumps(data, ensure_ascii=False, indent=2, default=str)
    except (TypeError, ValueError):
        return False
    try:
        fd, tmp = tempfile.mkstemp(
            prefix=f".{path.name}.",
            suffix=".tmp",
            dir=str(path.parent),
        )
    except OSError:
        return False
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(encoded)
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    except OSError:
        if os.path.exists(tmp):
            try:
                os.unlink(tmp)
            except OSError:
                pass
        return False
    return True

