def _build_initial_settings(registry: AddonRegistry) -> MarketplaceSettings:
    settings = MarketplaceSettings()
    for tab in registry.tab_order():
        settings.enabled[tab] = set()
        for addon in registry.scan(tab):
            if addon.enabled:
                settings.enabled[tab].add(addon.name)
    return settings

def marketplace_summary(registry: AddonRegistry | None = None) -> str:
    """Return a text summary of enabled/disabled addons across all tabs."""
    reg = registry or AddonRegistry()
    parts: list[str] = []
    for tab in reg.tab_order():
        addons = reg.scan(tab)
        on = sum(1 for a in addons if a.enabled)
        off = len(addons) - on
        parts.append(f"{reg.tab_label(tab)}: {on}(+{off})")
    return "  ".join(parts)

def _search_transcript_jsonl(
    rx: re.Pattern,
    hits: list[dict[str, str]],
    limit: int,
) -> None:
    path = Path(_TRANSCRIPT_JSONL)
    if not path.exists():
        return
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return
    for raw in reversed(lines):
        if len(hits) >= limit:
            break
        try:
            entry = json.loads(raw)
        except json.JSONDecodeError:
            continue
        cmd = entry.get("command", "")
        output = entry.get("output", "")
        for text_line in (output or "").splitlines():
            if len(hits) >= limit:
                break
            if rx.search(text_line):
                hits.append(
                    {
                        "source": "transcript",
                        "context": cmd[:20],
                        "line": text_line.strip()[:120],
                    }
                )

def _search_csv(rx: re.Pattern, hits: list[dict[str, str]], limit: int) -> None:
    path = Path(_SESSION_CSV)
    if not path.exists():
        return
    try:
        with path.open("r", encoding="utf-8", errors="ignore") as fh:
            reader = csv.DictReader(fh)
            rows = list(reader)
    except (OSError, csv.Error):
        return
    for row in reversed(rows):
        if len(hits) >= limit:
            break
        for col, val in row.items():
            if val and rx.search(val):
                hits.append(
                    {
                        "source": "session.csv",
                        "context": col,
                        "line": str(val).strip()[:120],
                    }
                )
                break

def _search_logs(
    rx: re.Pattern,
    hits: list[dict[str, str]],
    limit: int,
    sessions_dir: str,
) -> None:
    logs_dir = Path(sessions_dir) / "logs"
    if not logs_dir.is_dir():
        return
    for fpath in sorted(logs_dir.rglob("*.txt"), key=lambda p: p.stat().st_mtime, reverse=True):
        if len(hits) >= limit:
            break
        try:
            content = fpath.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for line in content.splitlines():
            if len(hits) >= limit:
                break
            if rx.search(line):
                hits.append(
                    {
                        "source": fpath.name[:18],
                        "context": "",
                        "line": line.strip()[:120],
                    }
                )

