class TelemetryIndexError(RuntimeError):
    """Raised when the telemetry CSV is malformed in a way callers must see."""


@dataclass(frozen=True)

def _normalise_command(value: str | None, *, prefix: str) -> str:
    """Return the canonical ``do_<verb>`` form for a CSV ``command`` field."""
    if not isinstance(value, str):
        return ""
    raw = value.strip()
    if not raw:
        return ""
    return raw if raw.startswith(prefix) else f"{prefix}{raw}"

def _read_csv_rows(path: Path) -> list[dict[str, str]]:
    """Return the parsed rows of ``path``.

    A missing file returns an empty list so the loader stays best-effort.
    Rows lacking the ``command`` column are dropped silently.
    """
    if not path.exists():
        return []
    try:
        with path.open(newline="", encoding="utf-8", errors="replace") as fh:
            reader = csv.DictReader(fh)
            return [dict(row) for row in reader if isinstance(row, dict)]
    except (OSError, csv.Error) as exc:
        raise TelemetryIndexError(f"Cannot read telemetry from {path}: {exc}") from exc

def safe_load_telemetry(path: str | None = None) -> TelemetryIndex | None:
    """Best-effort variant of :func:`load_telemetry`.

    Returns ``None`` instead of raising so the palette stays usable on hosts
    where the CSV is malformed.
    """
    try:
        return load_telemetry(path)
    except TelemetryIndexError:
        return None

def recents(
    telemetry: TelemetryIndex | None,
    *,
    config: TelemetryConfig | None = None,
) -> list[str]:
    """Return the most-recently invoked unique ``do_*`` commands.

    Order is most-recent-first; truncated to
    :attr:`TelemetryConfig.recents_limit` entries.
    """
    cfg = config or TelemetryConfig()
    if telemetry is None:
        return []
    return list(telemetry.recent_order[: cfg.recents_limit])

def load_tier_manifest(manifest: str | Path) -> dict[str, str]:
    """Load explicit tier overrides from a ``tiers.yaml`` manifest.

    Args:
        manifest: Path to a YAML mapping of plugin name to tier.

    Returns:
        Mapping of plugin name to tier. Unknown tiers and malformed
        entries are ignored so a bad manifest can never break listing.
    """
    path = Path(manifest)
    if not path.is_file():
        return {}
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except (yaml.YAMLError, OSError, UnicodeDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    tiers: dict[str, str] = {}
    for name, tier in data.items():
        if isinstance(name, str) and isinstance(tier, str) and tier in KNOWN_TIERS:
            tiers[name] = tier
    return tiers

def _load_ratings(store: str | Path) -> dict[str, list[int]]:
    path = Path(store)
    if not path.is_file():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, UnicodeDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    ratings: dict[str, list[int]] = {}
    for name, votes in data.items():
        if isinstance(name, str) and isinstance(votes, list):
            clean = [v for v in votes if isinstance(v, int) and 1 <= v <= 5]
            if clean:
                ratings[name] = clean
    return ratings

def rating_summary(name: str, store: str | Path) -> tuple[float, int]:
    """Return the ``(average, count)`` rating for a plugin name.

    Args:
        name: Plugin/addon/tool stem.
        store: JSON file holding the ratings map.

    Returns:
        ``(0.0, 0)`` when nobody rated the plugin yet.
    """
    votes = _load_ratings(store).get(name, [])
    if not votes:
        return (0.0, 0)
    return (round(sum(votes) / len(votes), 2), len(votes))

