    cfg = config or TimelineConfig()
    root = Path(sessions_dir) if sessions_dir and sessions_dir.strip() else Path(cfg.sessions_dir)
    reader = TimelineReader(cfg, root=root)
    return TimelineState(config=cfg, reader=reader)

