        return ""
    normalized = cmd if cmd.startswith("do_") else f"do_{cmd}"
    cmds = self._index.get("commands", [])
    if isinstance(cmds, list):
        for entry in cmds:
            if isinstance(entry, dict) and entry.get("name") in (normalized, cmd):
