@staticmethod

def _get_karma_name(elo: int) -> str:
    for threshold, label in KARMA_THRESHOLDS:
        if elo < threshold:
            return label
    return KARMA_TOP

def _next_threshold(self, current: int) -> int:
    gap = max(2, int(round(-self.config.mean_interval * math.log(max(random.random(), 1e-9)))))
    return current + gap

def _sync_user_elo(self, delta: int) -> bool:
    if delta <= 0:
        return False
    target: str | None = None
    try:
        from modules.cli_auth import get_current_operator

        target = get_current_operator()
    except ImportError:
        pass
    if not target:
        target = self._load_payload().get("c2_user")
    if not target:
        return False
    try:
        from modules.lazy_rbac import get_rbac_store

        store = get_rbac_store()
        user = store.find_by_username(target)
        if user:
            user.elo = int(user.elo or 0) + int(delta)
            store.save(user)
            return True
    except ImportError:
        pass
    users_path = Path(self.config.users_path)
    if not users_path.exists():
        return False
    try:
        users: Any = json.loads(users_path.read_text(encoding="utf-8"))
        if not isinstance(users, list):
            return False
        modified = False
        for record in users:
            if isinstance(record, dict) and record.get("username") == target:
                record["elo"] = int(record.get("elo", 0)) + int(delta)
                modified = True
                break
        if not modified:
            return False

def path(self) -> Path:
    """Return the resolved state-file path."""
    return self._path

def get(self, name: str) -> int:
    """Return the persisted offset for ``name`` or 0."""
    self._ensure_loaded()
    return int(self._offsets.get(name, 0))

def reset(self) -> None:
    """Forget every persisted offset (force replay on next read)."""
    self._offsets = {}
    self._loaded = True

def _ensure_loaded(self) -> None:
    if self._loaded:
        return
    self._loaded = True
    if not self._path.is_file():
        return
    try:
        raw = self._path.read_text(encoding="utf-8")
        data = json.loads(raw) if raw else {}
    except (OSError, ValueError, json.JSONDecodeError):
        return
    offsets = data.get("offsets") if isinstance(data, dict) else None
    if not isinstance(offsets, dict):
        return
    for key, value in offsets.items():
        if not isinstance(key, str):
            continue
        if isinstance(value, (int, float)):
            self._offsets[key] = max(0, min(int(value), self._config.max_offset_value))

def root(self) -> Path:
    """Return the resolved events root directory."""
    return self._root

def _build_event(self, line: str, source: str, offset: int) -> ToastEvent | None:
    try:
        record = json.loads(line)
    except (ValueError, json.JSONDecodeError):
        return None
    if not isinstance(record, dict):
        return None
    event_type = self._coerce_str(record.get("type") or record.get("kind") or record.get("event") or "")
    severity = self._coerce_str(record.get("severity") or record.get("status") or record.get("level") or "info")
    timestamp = self._coerce_str(record.get("ts") or record.get("timestamp") or "")
    summary = self._summary(record)
    return ToastEvent(
        source=source,
        offset=offset,
        event_type=event_type or "event",
        severity=severity or "info",
        summary=summary,
        timestamp=timestamp,
    )

@staticmethod

def _coerce_str(value: Any) -> str:
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, (int, float, bool)):
        return str(value)
    return ""

@staticmethod

def _summary(record: Mapping[str, Any]) -> str:
    payload = record.get("payload") if isinstance(record.get("payload"), dict) else {}
    for source in (record, payload):
        for key in ("message", "summary", "detail", "goal", "command", "target"):
            value = source.get(key) if isinstance(source, Mapping) else None
            if isinstance(value, str) and value.strip():
                return value.strip()
            if isinstance(value, (int, float, bool)):
                return str(value)
    return ""

def _console_width(self) -> int:
    """Return a sane console width when the caller passes none."""
    try:
        return int(Console().width)
    except Exception:
        return self._config.fallback_width

def _role_for(self, severity: str) -> str:
    lookup = self._config.severity_styles.get(severity.lower())
    if lookup:
        return lookup
    return self._config.default_role

def _truncate(self, value: str) -> str:
    from core.text_utils import truncate_text

    return truncate_text(value, self._config.max_line_chars, marker=self._config.truncation_suffix)

def collect(self) -> list[ToastEvent]:
    """Return every unseen event across :attr:`ToastConfig.event_files`."""
    out: list[ToastEvent] = []
    for name in self._config.event_files:
        start = self._state.get(name)
        events, end = self._reader.read_unseen(name, start)
        if events:
            out.extend(events)
        if end > start:
            self._state.set(name, end)
    return out

def mark_all_seen(self) -> None:
    """Advance the offset for every configured file to its current size."""
    for name in self._config.event_files:
        _, end = self._reader.read_unseen(name, 0)
        self._state.set(name, end)
    self._state.flush()

def _is_truthy(value: Any, config: ToastConfig, default: bool) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in config.truthy_strings:
            return True
        if lowered in config.falsy_strings:
            return False
    return default

def toasts_enabled(payload: Mapping[str, Any] | None, config: ToastConfig | None = None) -> bool:
    """Return ``True`` when toast rendering is permitted."""
    cfg = config or ToastConfig()
    if payload is None:
        return cfg.enabled_default
    return _is_truthy(payload.get(cfg.enabled_key), cfg, cfg.enabled_default)

def _budget(payload: Mapping[str, Any] | None, config: ToastConfig) -> int:
    if payload is None:
        return config.max_per_tick_default
    raw = payload.get(config.max_per_tick_key)
    if isinstance(raw, bool):
        return config.max_per_tick_default
    if isinstance(raw, (int, float)):
        candidate = int(raw)
    elif isinstance(raw, str) and raw.strip().isdigit():
        candidate = int(raw.strip())
    else:
        return config.max_per_tick_default
    return max(1, min(candidate, 50))

def is_done(config: TutorialConfig | None = None) -> bool:
    """Return True if the tutorial has already been completed."""
    cfg = config or TutorialConfig()
    return cfg.done_marker.exists()

