def makeRecord(
    self,
    name: str,
    level: int,
    fn: str,
    lno: int,
    msg: object,
    args: Any,
    exc_info: Any,
    func: str | None = None,
    extra: Mapping[str, object] | None = None,
    sinfo: str | None = None,
) -> logging.LogRecord:
    record = super().makeRecord(
        name,
        level,
        fn,
        lno,
        msg,
        args,
        exc_info,
        func,
        extra,
        sinfo,
    )
    if extra:
        for key, value in extra.items():
            setattr(record, f"_extra_{key}", value)
            setattr(record, key, value)
    return record

def get_network_info() -> dict[str, Any]:
    """Collect local network information.

    Returns:
        Dict with keys ``hostname``, ``ips``, ``interfaces``.
    """
    import netifaces

    info: dict[str, Any] = {"hostname": socket.gethostname(), "ips": [], "interfaces": {}}
    try:
        info["ips"].append(socket.gethostbyname(socket.gethostname()))
    except socket.gaierror:
        pass
    try:
        for iface in netifaces.interfaces():
            addrs = netifaces.ifaddresses(iface)
            info["interfaces"][iface] = {k: [a.get("addr") for a in v if a.get("addr")] for k, v in addrs.items()}
            if netifaces.AF_INET in addrs:
                for a in addrs[netifaces.AF_INET]:
                    ip = a.get("addr")
                    if ip and ip not in info["ips"]:
                        info["ips"].append(ip)
    except Exception:
        pass
    return info


