@dataclass(frozen=True)

def __init__(self) -> None:
    self._lock = threading.RLock()
    self._tasks: dict[str, _TaskInfo] = {}
    self._running = False
    self._std_event: threading.Event | None = None
    self._std_thread: threading.Thread | None = None
    if _HAS_APSCHEDULER:
        self._backend: Any = _apbg.BackgroundScheduler(daemon=True)
    else:
        self._backend = sched.scheduler(time.time, time.sleep)

@classmethod

def instance(cls) -> TaskScheduler:
    """Return the singleton ``TaskScheduler`` instance."""
    if cls._instance is None:
        with cls._instance_lock:
            if cls._instance is None:
                cls._instance = cls()
    return cls._instance

def stop(self) -> None:
    """Stop the scheduler and cancel all pending tasks.

    Idempotent: calling ``stop()`` on an already-stopped scheduler is a
    no-op.
    """
    with self._lock:
        if not self._running:
            return
        self._running = False
        if _HAS_APSCHEDULER:
            self._backend.shutdown(wait=False)
        else:
            if self._std_event:
                self._std_event.set()
            for _ in range(len(self._backend.queue)):
                try:
                    self._backend.cancel(self._backend.queue[0])
                except (ValueError, IndexError):
                    break
        self._tasks.clear()
        log.info("Scheduler stopped")

def _cancel_internal(self, name: str) -> None:
    """Cancel a task without holding ``_lock``.

    Called from within locked sections only.
    """
    if _HAS_APSCHEDULER:
        job = self._backend.get_job(name)
        if job:
            job.remove()
    else:
        info = self._tasks.get(name)
        if info:
            info.active = False

def _wrapper() -> None:
    if not info.active or not self._running:
        return
    try:
        info.func()
    except Exception:
        log.exception("Recurring task %s failed", info.name)
    if info.active and self._running:
        info.next_run = time.time() + info.interval_seconds
        self._backend.enter(info.interval_seconds, 0, _wrapper)

self._backend.enter(info.interval_seconds, 0, _wrapper)

def _wrapper() -> None:
    try:
        func()
    except Exception:
        log.exception("One-shot task %s failed", name)
    finally:
        with self._lock:
            self._tasks.pop(name, None)

return _wrapper

def _run_stdlib_loop(self) -> None:
    """Main loop for the stdlib scheduler backend.

    Runs sched actions in a tight loop with a periodic check on the stop
    event, so ``stop()`` is responsive even when no events are pending.
    """
    delay = 0.5
    while self._running and not (self._std_event and self._std_event.is_set()):
        self._backend.run(blocking=False)
        time.sleep(delay)
    try:
        while not self._backend.empty():
            self._backend.run(blocking=False)
    except Exception:
        pass

def get_scheduler() -> TaskScheduler:
    """Return the singleton ``TaskScheduler`` instance."""
    return TaskScheduler.instance()

def anti_debug() -> None:
    """Check for debugger attachment and exit if found.

    Reads ``/proc/self/status`` for ``TracerPid``. If a tracer is
    attached and we are not running under a legitimate dev tool
    (gdb, strace, ltrace will show), the process exits immediately.

    This is called at import time by both ``lazyown.py`` and
    ``lazyc2.py``.
    """
    tracer_pid = 0
    try:
        with open("/proc/self/status") as f:
            for line in f:
                if line.startswith("TracerPid:"):
                    tracer_pid = int(line.split(":")[1].strip())
                    break
    except (OSError, ValueError, IndexError):
        return

    if tracer_pid > 0:
        try:
            PR_SET_PTRACER = 0x59616D61
            libc = ctypes.CDLL("libc.so.6")
            libc.prctl(PR_SET_PTRACER, 0, 0, 0, 0)
        except Exception:
            pass

    # ptrace-attempt based anti-debug — if we can ptrace ourselves,
    # no one else is attached. If the call fails, we are being traced.
    try:
        libc = ctypes.CDLL("libc.so.6")
        PTRACE_TRACEME = 0
        result = libc.ptrace(PTRACE_TRACEME, 0, 0, 0)
        if result == -1:
            os._exit(1)
    except Exception:
        os._exit(1)

def _rejects_shell_meta(value: str) -> bool:
    """Return True when value contains characters usable for shell injection."""
    return any(ch in _SHELL_META_CHARS for ch in value)

def _is_valid_host(value: object) -> bool:
    """Check value is a plain IP, CIDR, or hostname without shell metacharacters."""
    if not isinstance(value, str):
        return False
    text = value.strip()
    if not text or len(text) > 253 or _rejects_shell_meta(text):
        return False
    import ipaddress

    candidate = text.split("/")[0] if "/" in text else text
    try:
        ipaddress.ip_address(candidate)
        return "/" not in text or _is_valid_cidr(text)
    except ValueError:
        pass
    if "/" in text:
        return _is_valid_cidr(text)
    return _HOST_RE.match(text) is not None

def _is_valid_cidr(value: str) -> bool:
    """Check value is a valid CIDR block."""
    import ipaddress

    try:
        ipaddress.ip_network(value, strict=False)
        return True
    except ValueError:
        return False

