# Open a new pane (split v or h), start LazyOwn shell with optional run flags,
# then send any follow-up commands once the shell is up.
# Usage: t_lazyown <v|h> <delay_secs> <run_flags> [cmd1] [cmd2] ...

usage() {
    grep '^#' "$0" | grep -v '^#!' | sed 's/^# \{0,1\}//'
}

while [[ "$#" -gt 0 ]]; do
    arg="$1"
    shift
    case "$arg" in
        --with-ml) WITH_ML=1 ;;
        --with-ollama) WITH_OLLAMA=1 ;;
        --with-tools) WITH_TOOLS=1 ;;
        --profile)
            [[ "$#" -ge 1 ]] || { echo "[!] --profile requires an argument: light or full." >&2; exit 2; }
            PROFILE="$1"
            shift
            ;;
        --profile=*) PROFILE="${arg#--profile=}" ;;
        --no-ml) WITH_ML=0 ;;
        --no-ollama) WITH_OLLAMA=0 ;;
        -h | --help)
            usage
            exit 0
            ;;
        *)
            echo "[!] Unknown option: $arg" >&2
            usage >&2
            exit 2
            ;;
    esac
done

case "$PROFILE" in
    light | full) ;;
    *)
        echo "[!] --profile must be 'light' or 'full' (got '$PROFILE')." >&2
