def select_relevant_chunk(self, file_content, chunks):
    if not chunks:
        return ""
    file_words = set(re.findall(r'\w+', file_content.lower()))
    best_chunk = chunks[0]
    max_overlap = 0
    for chunk in chunks:
        chunk_words = set(re.findall(r'\w+', chunk.lower()))
        overlap = len(file_words & chunk_words)
        if overlap > max_overlap:
            max_overlap = overlap
            best_chunk = chunk
    return best_chunk

