def _show_selected_info(self) -> None:
    current_tab = self._tabs.currentWidget()
    if current_tab is self._yara_tree:
        self._backend.send_command("yara_marketplace list", target_session=None)
    elif current_tab is self._nuclei_tree:
        self._backend.send_command("nuclei_marketplace list", target_session=None)
    elif current_tab is self._addons_tree:
        self._backend.send_command("marketplace list", target_session=None)
    elif current_tab is self._plugins_tree:
        self._backend.send_command("plugins list", target_session=None)

def _run_selected(self) -> None:
    current_tab = self._tabs.currentWidget()
    items = current_tab.selectedItems() if current_tab else []
    if not items:
        return
    name = items[0].text(0)
    if current_tab is self._yara_tree:
        self._backend.send_command(f"yara_scan {name}", target_session=None)
    elif current_tab is self._nuclei_tree:
        self._backend.send_command(f"nuclei -t {name}", target_session=None)
    elif current_tab is self._addons_tree:
        self._backend.send_command(f"use {name}\nrun", target_session=None)
    elif current_tab is self._plugins_tree:
        self._backend.send_command(f"plugin load {name}", target_session=None)

def all_panels(self) -> tuple[PanelBase, ...]:
    """Return panels in canonical layout order."""
    return (
        self.graph, self.sessions, self.listeners, self.killchain,
        self.credentials, self.marketplace, self.campaign, self.cve,
        self.history, self.terminal, self.event_log_panel,
    )

def by_identifier(self, identifier: str) -> PanelBase:
    """Look up a panel by its stable identifier."""
    for panel in self.all_panels():
        if panel.identifier == identifier:
            return panel
    raise KeyError(f"Unknown panel identifier: {identifier!r}")

def __iter__(self) -> Iterator[PanelBase]:
    """Iterate over panels in canonical order."""
    return iter(self.all_panels())

def _refresh_initial(self) -> None:
    """Render any sessions the backend already had at construction time."""
    initial = self._backend.known_sessions()
    if initial:
        self._on_sessions_changed(list(initial))

def _on_selection_changed(self) -> None:
    """Emit ``session_selected`` for the currently highlighted row."""
    items = self._tree.selectedItems()
    if not items:
        return
    identifier = items[0].text(_ID_COLUMN)
    for session in self._sessions:
        if session.identifier == identifier:
            self.session_selected.emit(session)
            return

def focus_terminal(self) -> None:
    """Move keyboard focus into the terminal text area."""
    self._terminal.setFocus()

def set_target_session(self, session_id: str) -> None:
    """Select a specific beacon in the dropdown."""
    for i in range(self._session_combo.count()):
        data = self._session_combo.itemData(i, Qt.ItemDataRole.UserRole)
        if data == session_id:
            self._session_combo.setCurrentIndex(i)
            return

def _send_beacon_command(self) -> None:
    """Send the typed command to the selected beacon or C2 server."""
    command = self._cmd_input.text().strip()
    if not command:
        return
    self._cmd_input.clear()
    target = self._session_combo.currentData(Qt.ItemDataRole.UserRole)
    target_label = self._session_combo.currentText()
    if target is None:
        self._backend.send_command(command, target_session=None)
    else:
        self._backend.send_command(command, target_session=str(target))
    self._terminal.append_output(f"\n[{target_label}] $ {command}\n")

def _on_beacon_result(self, result) -> None:
    """Display beacon command results in the terminal."""
    self._terminal.append_output(
        f"\n=== [{result.client_id}] {result.command} ===\n{result.output}\n=== END ===\n"
    )

