def request_session_state(self) -> dict:
    """Request the current session state (creds, hashes, loot) as a dict."""
    result: dict[str, list] = {"credentials": [], "hashes": [], "loot": []}
    try:
        from pathlib import Path
        sessions_dir = Path("sessions")
        for fpath in sorted(sessions_dir.glob("credentials*.txt")):
            for line in fpath.read_text(encoding="utf-8", errors="ignore").splitlines():
                line = line.strip()
                if line and not line.startswith("#"):
                    parts = line.split(":", 2)
                    result["credentials"].append({
                        "username": parts[0] if parts else "",
                        "type": parts[1] if len(parts) > 1 else "password",
                        "source": fpath.name,
                    })
        for fpath in sorted(sessions_dir.glob("hash*")):
            for line in fpath.read_text(encoding="utf-8", errors="ignore").splitlines():
                line = line.strip()
                if line:
                    result["hashes"].append(line)
        loot_dir = sessions_dir / "loot"
        if loot_dir.exists():
            for fpath in sorted(loot_dir.iterdir()):
                if fpath.is_file():
                    result["loot"].append({"name": fpath.name, "size": str(fpath.stat().st_size)})
    except Exception:
        pass
    return result

def __init__(self, constants: AppConstants, parent: QObject | None = None) -> None:
    """Initialise the buffer using ``constants.event_log.max_records``."""
    super().__init__(parent)
    self._capacity = constants.event_log.max_records
    self._records: deque[EventRecord] = deque(maxlen=self._capacity)

@property

def capacity(self) -> int:
    """Maximum number of records retained before the oldest is dropped."""
    return self._capacity

def extend(self, records: Iterable[EventRecord]) -> None:
    """Append every entry in ``records`` in iteration order."""
    for record in records:
        self.append(record)

def snapshot(self, minimum_level: EventLevel | None = None) -> tuple[EventRecord, ...]:
    """Return a defensive tuple, optionally filtered by ``minimum_level``."""
    if minimum_level is None:
        return tuple(self._records)
    threshold = minimum_level.numeric
    return tuple(record for record in self._records if record.level.numeric >= threshold)

def create_local(self, parent: QObject | None = None) -> LocalPtyBackend:
    """Construct a local PTY-based backend."""
    return LocalPtyBackend(constants=self.constants, paths=self.paths, parent=parent)

def create_teamserver(
    self,
    credentials: TeamserverCredentials,
    parent: QObject | None = None,
) -> TeamserverBackend:
    """Construct a teamserver-based backend with the given credentials."""
    return TeamserverBackend(constants=self.constants, credentials=credentials, parent=parent)

def create(
    self,
    kind: BackendKind,
    parent: QObject | None = None,
    credentials: TeamserverCredentials | None = None,
) -> Backend:
    """Convenience dispatch by :class:`BackendKind`."""
    if kind is BackendKind.LOCAL:
        return self.create_local(parent=parent)
    if kind is BackendKind.TEAMSERVER:
        if credentials is None:
            raise ValueError("Teamserver backend requires credentials.")
        return self.create_teamserver(credentials=credentials, parent=parent)
    raise ValueError(f"Unsupported backend kind: {kind!r}")

def stop(self) -> None:
    """Send ``SIGTERM`` to the child and tear down notifiers."""
    if self._notifier is not None:
        self._notifier.setEnabled(False)
        self._notifier.deleteLater()
        self._notifier = None
    if self._reaper is not None:
        self._reaper.stop()
        self._reaper.deleteLater()
        self._reaper = None
    if self._child_pid is not None:
        try:
            os.kill(self._child_pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        self._child_pid = None
    if self._master_fd is not None:
        try:
            os.close(self._master_fd)
        except OSError:
            pass
        self._master_fd = None
    self._set_status(BackendStatus.DISCONNECTED)
    self._emit_event(EventLevel.INFO, "Local console stopped.")

def refresh(self) -> None:
    """No-op for the local backend; the operator drives data from cmd2."""
    self._emit_event(EventLevel.DEBUG, "Local backend refresh requested (no-op).")

def feed_terminal_input(self, data: str) -> None:
    """Encode ``data`` and write it to the master end of the PTY."""
    if self._master_fd is None:
        return
    encoded = data.encode(self._constants.pty.encoding, errors=self._constants.pty.encoding_errors)
    try:
        os.write(self._master_fd, encoded)
    except OSError as exc:
        self._emit_event(EventLevel.ERROR, f"PTY write failed: {exc}")

