    zoom_in = event.angleDelta().y() > 0
    factor = self._ZOOM_FACTOR if zoom_in else 1.0 / self._ZOOM_FACTOR
    current = self.transform().m11()
    if factor > 1.0 and current >= self._MAX_ZOOM:
