class TerminalView(QPlainTextEdit):
    """Plain-text view that consumes backend output and emits keystrokes."""

    input_typed = Signal(str)

def keyPressEvent(self, event: QKeyEvent) -> None:
    """Forward keystrokes to listeners instead of mutating the buffer."""
    text_segment = self._translate_key_event(event)
    if text_segment is not None:
        self.input_typed.emit(text_segment)
        event.accept()
        return
    super().keyPressEvent(event)

@staticmethod

def _translate_key_event(event: QKeyEvent) -> str | None:
    """Return the raw bytes a backend should receive, or ``None`` to ignore."""
    if event.modifiers() & Qt.KeyboardModifier.ControlModifier and event.key() in (
        Qt.Key.Key_C,
        Qt.Key.Key_V,
        Qt.Key.Key_A,
        Qt.Key.Key_Plus,
        Qt.Key.Key_Minus,
    ):
        return None
    key = event.key()
    if key == Qt.Key.Key_Return or key == Qt.Key.Key_Enter:
        return "\n"
    if key == Qt.Key.Key_Backspace:
        return "\x7f"
    if key == Qt.Key.Key_Tab:
        return "\t"
    if key == Qt.Key.Key_Up:
        return "\x1b[A"
    if key == Qt.Key.Key_Down:
        return "\x1b[B"
    if key == Qt.Key.Key_Right:
        return "\x1b[C"
    if key == Qt.Key.Key_Left:
        return "\x1b[D"
    text = event.text()
    if text:
        return text
    return None

def request(self) -> ConnectionRequest:
    """Translate current widget state into a :class:`ConnectionRequest`."""
    kind = self._kind_combo.currentData(role=Qt.ItemDataRole.UserRole)
    if kind is BackendKind.LOCAL:
