    index = len(tokens) - (0 if line[:endidx].endswith(" ") else 1)
    if index == 1:
        return [a for a in ("add", "rm", "clear", "mode") if a.startswith(text)]
    if index == 2 and tokens[1].lower() == "mode":
        return [m for m in ("off", "warn", "enforce") if m.startswith(text)]
