def __init__(self, name: str, description: str, func: Callable,
             parameters: dict[str, Any], required: list[str] = None):
    self.name = name
    self.description = description
    self.func = func
    self.parameters = {
        "type": "object",
        "properties": parameters,
        "required": required or list(parameters.keys())
    }

def to_api_format(self) -> dict[str, Any]:
    """Convierte al formato API de LLM (Groq/Ollama)"""
    return {
        "type": "function",
        "function": {
            "name": self.name,
            "description": self.description,
            "parameters": self.parameters
        }
    }

def execute(self, **kwargs) -> str:
    """Ejecuta la herramienta con manejo de errores robusto"""
    try:
        result = self.func(**kwargs)
        return json.dumps({"success": True, "result": result})
    except Exception as e:
        error_msg = f"Error ejecutando {self.name}: {str(e)}"
        logging.error(error_msg)
        return json.dumps({"success": False, "error": error_msg})

def __init__(self) -> None:
    self._adaptation_log: list[dict[str, Any]] = []
    self._confidence_boost: dict[str, int] = {}
    self._base_scores: dict[str, float] = {
        DIRECT: 0.6, BRUTE_FORCE: 0.4, PATH_TRAVERSAL: 0.3,
        DESERIALIZATION: 0.2, COMMAND_INJECTION: 0.4, SQL_INJECTION: 0.3,
        AUTH_BYPASS: 0.3, PRIVESC_LINUX: 0.5, PRIVESC_WINDOWS: 0.5,
        LATERAL_SMB: 0.6, LATERAL_WINRM: 0.5, LATERAL_SSH: 0.5,
        PIVOT_SOCKS: 0.3, WEB_ENUM: 0.7, NULL_SESSION: 0.6,
        CREDENTIAL_REUSE: 0.5, UNAUTH_ACCESS: 0.5, ENUMERATION: 0.8,
        KNOWN_EXPLOIT: 0.7, ANONYMOUS_LOGIN: 0.4,
    }

def reason(self, context: ExploitChainContext) -> ExploitCandidate | None:
    """Analyze context failures and produce the next best exploit candidate."""
    if context.attempted and not context.attempted[-1].success:
        context.failed_strategies.append(
            context.attempted[-1].candidate.strategy
        )

    strategy = self.select_next_strategy(context)
    if not strategy:
        return None

    confidence = self.estimate_confidence(strategy, context.profile)
    context.current_phase = STRATEGY_PHASE.get(strategy, "exploitation")

    return ExploitCandidate(
        service=strategy, product="", version="",
        confidence=confidence, strategy=strategy,
    )

@staticmethod

def evaluate_failure(result: ExploitResult) -> str:
    """Classify the reason for an exploit failure by output pattern matching.

    Returns a failure category string (e.g. ``auth_required``).
    """
    combined = f"{result.output}\n{result.error}".lower()
    for category, patterns in FAILURE_SIGNATURES.items():
        for pattern in patterns:
            if re.search(pattern, combined, re.IGNORECASE):
                return category
    return "payload_blocked"

def select_next_strategy(self, context: ExploitChainContext) -> str:
    """Select the next strategy to attempt based on context and failures.

    Priority: adaptation from last failure, phase-aware escalation,
    service-based heuristics, then highest confidence remaining.
    """
    available = [s for s in context.available_strategies
                   if s not in context.failed_strategies]
    if not available:
        return ""

    adapted: list[str] = []
    if context.attempted and not context.attempted[-1].success:
        last_failure = self.evaluate_failure(context.attempted[-1])
        adapted = STRATEGY_ADAPTATIONS.get(last_failure, [])

    for strategy in adapted:
        if strategy in available:
            return strategy

    phase_strategies = [
        s for s, p in STRATEGY_PHASE.items()
        if p == context.current_phase and s in available
    ]
    for strategy in phase_strategies:
        if strategy in available:
            return strategy

    scored = sorted(
        [(s, self.estimate_confidence(s, context.profile)) for s in available],
        key=lambda item: item[1], reverse=True,
    )
    return scored[0][0] if scored else ""

