def adapt_chain(
    self, context: ExploitChainContext, new_info: dict[str, Any],
) -> list[dict[str, Any]]:
    """Adapt the chain plan based on newly discovered information.

    Unlocks strategies based on new creds, ports, OS details, and
    parses shell output for privilege escalation hints.

    Args:
        context: Current exploit chain state.
        new_info: Dict with optional keys ``credentials``,
            ``open_ports``, ``os_type``, ``os_version``,
            ``access_level``, ``shell_output``.

    Returns:
        Rebuilt chain plan reflecting the new information.
    """
    self._adaptation_log.append({
        "before": context.current_phase, "new_info": list(new_info.keys()),
    })

    shell_output = new_info.get("shell_output", "")
    if shell_output:
        self._parse_shell_hints(shell_output, context)

    if new_info.get("credentials"):
        for s in (CREDENTIAL_REUSE, LATERAL_SSH, LATERAL_WINRM, LATERAL_SMB):
            self._ensure(context, s)

    for port in new_info.get("open_ports", []):
        for s in _PORT_STRATEGIES.get(port, ()):
            self._ensure(context, s)

    access = new_info.get("access_level", "")
    if access == "user":
        os_type = context.profile.os_type
        if os_type == "linux":
            self._ensure(context, PRIVESC_LINUX)
        elif os_type == "windows":
            self._ensure(context, PRIVESC_WINDOWS)

def _ensure(context: ExploitChainContext, strategy: str) -> None:
    """Add *strategy* to available_strategies if not already present."""
    if strategy not in context.available_strategies:
        context.available_strategies.append(strategy)

    def _parse_shell_hints(self, output: str, context: ExploitChainContext) -> None:
        """Detect privesc vectors and credentials in shell output."""
        output_lower = output.lower()

        if re.search(r"\(ALL\)", output):
            self._ensure(context, PRIVESC_LINUX)
            self._confidence_boost[PRIVESC_LINUX] = (
                self._confidence_boost.get(PRIVESC_LINUX, 0) + 1
            )
        elif any(binary in output for binary in _SUDO_PRIVESC_BINARIES):
            self._ensure(context, PRIVESC_LINUX)
            self._confidence_boost[PRIVESC_LINUX] = (
                self._confidence_boost.get(PRIVESC_LINUX, 0) + 1
            )
        elif "nopasswd" in output_lower:
            self._ensure(context, PRIVESC_LINUX)

        for priv in _WIN_PRIVESC_PRIVILEGES:
            if priv in output_lower and "enabled" in output_lower:
                self._ensure(context, PRIVESC_WINDOWS)
                self._confidence_boost[PRIVESC_WINDOWS] = (
                    self._confidence_boost.get(PRIVESC_WINDOWS, 0) + 2
                )
                break

        cred_patterns = [
            r"(?:username|user|login)[=:]\s*(\S+)",
            r"(?:password|pass|pwd)[=:]\s*(\S+)",
            r"(?:ntlm|ntlmv2|nt):\s*([a-fA-F0-9]{32,})",
        ]
        for pattern in cred_patterns:
            if re.search(pattern, output, re.IGNORECASE):
                for s in (CREDENTIAL_REUSE, LATERAL_SMB, LATERAL_WINRM, LATERAL_SSH):
                    self._ensure(context, s)
                break


