def _credential_aware_rank(
    self, profile: TargetProfile, credentials: list[dict[str, str]]
) -> list[ExploitCandidate]:
    """Re-rank exploit candidates boosting those usable with available credentials.

    Detects whether credentials are plaintext (user:pass), hash-based
    (NTLM), or empty and adjusts confidence scores accordingly.

    Args:
        profile: Target profile.
        credentials: List of credential dicts.

    Returns:
        Re-ranked list of ExploitCandidate sorted by boosted confidence.
    """
    candidates = self.rank_exploits(profile)
    has_plaintext = any(
        c.get("username") and c.get("password") for c in credentials
    )
    has_hash = any(
        c.get("hash") for c in credentials
    )
    has_any = bool(credentials)

    for candidate in candidates:
        base = candidate.confidence
        if candidate.strategy in ("brute_force",):
            if has_plaintext:
                candidate.confidence = min(base * 2.5, 1.0)
                candidate.requires_auth = True
            elif has_hash:
                candidate.confidence = min(base * 1.8, 1.0)
        elif candidate.strategy == "credential_reuse":
            if has_any:
                candidate.confidence = min(base * 3.0, 1.0)
                candidate.requires_auth = True
        elif candidate.strategy == "null_session":
            if has_plaintext:
                candidate.confidence = min(base * 2.2, 1.0)

def _filter_placeholder_creds(credentials: list[dict[str, str]]) -> list[dict[str, str]]:
    _PLACEHOLDER_TOKENS: set[str] = {
        "change_me", "changeme", "your_api_key_here", "your_api_key",
        "admin", "root", "password", "pass", "test", "guest", "anonymous",
    }

def _is_placeholder(value: str) -> bool:
    if not value:
        return True
    lower = value.lower().strip()
    if lower in _PLACEHOLDER_TOKENS:
        return True
    return any(len(t) > 5 and t in lower for t in _PLACEHOLDER_TOKENS)
filtered: list[dict[str, str]] = []
for cred in credentials:
    user = cred.get("username", "")
    passw = cred.get("password", "")
    val = cred.get("value", "")
    hsh = cred.get("hash", "")
    if hsh:
        if _is_placeholder(hsh):
            continue
        filtered.append(cred)
        continue
    if user and passw:
        if _is_placeholder(user) and _is_placeholder(passw):
            continue
        filtered.append(cred)
    elif val:
        if _is_placeholder(val):
            continue
        filtered.append(cred)
return filtered

def _run_exploit(
    self, candidate: ExploitCandidate, profile: TargetProfile
) -> str:
    """Execute the exploit through LazyOwn's command runner.

    Args:
        candidate: The exploit to run.
        profile: Target profile.

    Returns:
        Command output as string.
    """
    commands = self._build_command_chain(candidate, profile)
    output_parts: list[str] = []

    for cmd in commands:
        try:
            from core.safe_exec import safe_run_shell as _safe_shell
            proc = _safe_shell(cmd, allow=True, reason="exploit chain step, shell ops allowed", timeout=120, cwd=str(BASE_DIR))
            output_parts.append(proc.stdout)
            output_parts.append(proc.stderr)
        except subprocess.TimeoutExpired:
            output_parts.append(f"[timeout] {cmd}")
        except Exception as exc:
            output_parts.append(f"[error] {cmd}: {exc}")

    return "\n".join(output_parts)

def _resolve_port(
    self, candidate: ExploitCandidate, profile: TargetProfile
) -> str:
    """Resolve the actual port number for the candidate's service.

    Args:
        candidate: The exploit candidate.
        profile: Target profile with service details.

    Returns:
        Port number as string, or the service name if unresolvable.
    """
    if candidate.service.isdigit():
        return candidate.service
    for svc in profile.services:
        if svc.get("name") == candidate.service:
            return svc.get("port", candidate.service)
    return candidate.service

def _determine_access_level(
    self, ip: str, credentials: list[dict[str, str]]
) -> str:
    """Determine current access level to target.

    Args:
        ip: Target IP.
        credentials: Known credentials list.

    Returns:
        Access level string: none, user, admin, system.
    """
    sessions_file = SESSIONS_DIR / f"beacon_{ip.replace('.', '_')}.json"
    if sessions_file.exists():
        try:
            data = json.loads(sessions_file.read_text())
            if data.get("admin", False):
                return "admin"
            return "user"
        except (json.JSONDecodeError, OSError):
            pass

    if credentials:
        for cred in credentials:
            user = cred.get("username", "").lower()
            if user in ("administrator", "root", "nt authority\\system"):
                return "admin"
            if user:
                return "user"

    return "none"

