def _detect_os_from_payload(self) -> str | None:
    """Read os_id from payload.json and return OS type string.

    Returns:
        'linux', 'windows', or None if not set.
    """
    try:
        if PAYLOAD_PATH.exists():
            cfg = json.loads(PAYLOAD_PATH.read_text())
            os_id = str(cfg.get("os_id", "")).strip()
            if os_id == "1":
                return "linux"
            if os_id == "2":
                return "windows"
    except (json.JSONDecodeError, OSError):
        pass
    return None

def _load_from_nmap_xml(self, target: str) -> dict[str, Any]:
    """Fallback: parse nmap XML files for service data.

    Args:
        target: Target IP address.

    Returns:
        Dict with services or empty dict.
    """
    import xml.etree.ElementTree as ET

    services_list: list[dict[str, str]] = []
    open_ports: list[int] = []
    os_type = self._detect_os_from_payload() or "unknown"

    for xml_file in sorted(SESSIONS_DIR.glob(f"scan_{target}*.xml")):
        try:
            tree = ET.parse(str(xml_file))
            root = tree.getroot()
            for host_el in root.iter("host"):
                for addr_el in host_el.findall("address"):
                    if addr_el.get("addrtype") == "ipv4" and addr_el.get("addr") == target:
                        for os_el in host_el.findall("os"):
                            for match_el in os_el.findall("osmatch"):
                                os_name = match_el.get("name", "")
                                if "inux" in os_name.lower():
                                    os_type = "linux"
                                elif "indows" in os_name.lower():
                                    os_type = "windows"
                        for port_el in host_el.findall(".//port"):
                            state_el = port_el.find("state")
                            if state_el is not None and state_el.get("state") == "open":
                                pid = int(port_el.get("portid", 0))

def _parse_nse_output(self, target_ip: str) -> list[dict[str, Any]]:
    """Parse Nmap NSE vuln script output from sessions/ directory.

    Args:
        target_ip: Target IP address.

    Returns:
        List of parsed vulnerability dicts.
    """
    vulns: list[dict[str, Any]] = []
    safe_ip = target_ip.replace(".", "_")

    nse_patterns = [
        SESSIONS_DIR / f"scan_{safe_ip}.nmap",
        SESSIONS_DIR / f"vuln_{safe_ip}.txt",
        SESSIONS_DIR / f"nse_{safe_ip}.txt",
    ]
    for pattern in nse_patterns:
        if not pattern.exists():
            continue
        try:
            content = pattern.read_text(errors="replace")
            vulns.extend(self._extract_cves_from_text(content))
        except OSError:
            continue

    for txt_file in SESSIONS_DIR.glob(f"*vuln*{safe_ip}*.txt"):
        try:
            content = txt_file.read_text(errors="replace")
            vulns.extend(self._extract_cves_from_text(content))
        except OSError:
            continue

    return vulns

def _match_service_banners(self, profile: TargetProfile) -> list[dict[str, Any]]:
    """Heuristic vuln matching based on service banners from profile.

    Args:
