        Interface name (e.g. 'eth0', 'wlan0').
    """
    try:
        result = subprocess.run(
            ["ip", "route", "show", "default"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        for line in result.stdout.splitlines():
            parts = line.split()
            for i, part in enumerate(parts):
                if part == "dev" and i + 1 < len(parts):
                    return parts[i + 1]
    except Exception:
        pass

    try:
        result = subprocess.run(
            ["ip", "link", "show"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        for line in result.stdout.splitlines():
            if "state UP" in line:
                parts = line.split(":")
