@staticmethod

def _detect_compiler() -> tuple[str | None, str | None]:
    for name, args in [
        ("csc", ["-version"]),
        ("mcs", ["--version"]),
        ("dotnet", ["--version"]),
    ]:
        try:
            subprocess.run(
                [name] + args,
                capture_output=True,
                timeout=5,
            )
            return name, name
        except (FileNotFoundError, subprocess.TimeoutExpired):
            continue

    csc_paths = [
        r"C:\Windows\Microsoft.NET\Framework64\v4.0.30319\csc.exe",
        r"C:\Windows\Microsoft.NET\Framework\v4.0.30319\csc.exe",
        "/usr/bin/csc",
        "/usr/bin/mcs",
    ]
    for path in csc_paths:
        if os.path.isfile(path):
            for name in ("csc", "mcs"):
                if name in path:
                    return path, name
            return path, "csc"
    return None, None

