@staticmethod

def _extract_sid_from_file(filepath: str) -> str:
    try:
        with open(filepath, "rb") as f:
            f.read(SID_OFFSET)
            remaining = f.read()
            end = remaining.find(0)
            if end > 0:
                remaining = remaining[:end]
            return remaining.decode("utf-16-le", errors="replace").rstrip("\x00")
    except Exception:
        return ""

