def _compare_versions(version_a: str, version_b: str) -> int:
    """Compare two version strings.

    Returns -1 if a < b, 0 if equal, 1 if a > b.
    """
    try:
        clean_a = re.sub(r"[a-zA-Z].*", "", version_a.replace("_", "."))
        clean_b = re.sub(r"[a-zA-Z].*", "", version_b.replace("_", "."))
        parts_a = [int(x) for x in clean_a.split(".") if x]
        parts_b = [int(x) for x in clean_b.split(".") if x]
    except ValueError:
        return 0
    max_len = max(len(parts_a), len(parts_b))
    parts_a.extend([0] * (max_len - len(parts_a)))
    parts_b.extend([0] * (max_len - len(parts_b)))
    for a, b in zip(parts_a, parts_b, strict=False):
        if a < b:
            return -1
        if a > b:
            return 1
    return 0

def _discover_xml_files(self) -> list[str]:
    """Find all nmap XML files for the current rhost."""
    patterns = [
        os.path.join(self.sessions_dir, f"scan_{self.rhost}*.nmap.xml"),
        os.path.join(self.sessions_dir, f"vulns_{self.rhost}*.nmap.xml"),
    ]
    if self.nmap_xml_path and os.path.exists(self.nmap_xml_path):
        patterns.append(self.nmap_xml_path)
    files: set[str] = set()
    for pattern in patterns:
        for path in glob.glob(pattern):
            if os.path.isfile(path):
                files.add(path)
    return sorted(files)

def _parse_all_nmap_xml(self) -> list[ServiceInfo]:
    """Parse all available nmap XML files and merge results."""
    xml_files = self._discover_xml_files()
    if not xml_files:
        return []
    port_map: dict[tuple[int, str], ServiceInfo] = {}
    for xml_path in xml_files:
        for svc in self._parse_single_xml(xml_path):
            key = (svc.port, svc.protocol)
            existing = port_map.get(key)
            if existing is None or self._is_richer(svc, existing):
                port_map[key] = svc
    return sorted(port_map.values(), key=lambda s: s.port)

