def _load_exploitdb(self) -> None:
    edb_path = Path(EXPLOITDB_SEARCH)
    if not edb_path.exists():
        return
    try:
        with edb_path.open("r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                parts = line.strip().split(",")
                if len(parts) < 5:
                    continue
                edb_id = parts[0].strip('"')
                edb_file = parts[1].strip('"') if len(parts) > 1 else ""
                edb_desc = parts[2].strip('"') if len(parts) > 2 else ""
                edb_cves = parts[3].strip('"') if len(parts) > 3 else ""
                for cve in self._extract_cve_ids(edb_cves + " " + edb_desc):
                    self._exploitdb_index.setdefault(cve, []).append({
                        "edb_id": edb_id,
                        "file": edb_file,
                        "description": edb_desc,
                    })
    except OSError:
        pass

@staticmethod

def _extract_cve_ids(text: str) -> list[str]:
    return list(set(re.findall(r"CVE-\d{4}-\d{4,7}", text, re.IGNORECASE)))

@staticmethod

def _compare_versions(version: str, max_vulnerable: str) -> bool:
    if max_vulnerable == "0":
        return True
    try:
        v_installed = parse_version(version)
        v_max = parse_version(max_vulnerable)
        return v_installed <= v_max
    except Exception:
        return "unknown" in version.lower() or version == ""

