        stop)          cmd_stop "$@" ;;
        restart)       cmd_restart "$@" ;;
        status)        cmd_status "$@" ;;
        logs)          cmd_logs "$@" ;;
        chown-now)     cmd_chown_now "$@" ;;
        *)             usage; exit "$EXIT_USAGE" ;;
    esac
}

