def _qr_add_format_info(modules, size, ecl_bits, mask):
    fmt = (ecl_bits << 3) | mask
    fmt_val = fmt << 10
    fmt_poly = 0b10100110111
    for i in range(4, -1, -1):
        if fmt_val & (1 << (i + 10)):
            fmt_val ^= fmt_poly << i
    fmt_final = (fmt << 10) | (fmt_val & 0x3FF)
    fmt_final ^= 0b101010000010010

