        modules[i][8] = (fmt_final >> i) & 1
    modules[7][8] = (fmt_final >> 6) & 1
    modules[8][8] = (fmt_final >> 7) & 1
    modules[8][7] = (fmt_final >> 8) & 1
    for i in range(6):
        modules[8][5 - i] = (fmt_final >> (9 + i)) & 1
    for i in range(7):
        modules[size - 1 - i][8] = (fmt_final >> i) & 1
    for i in range(8):
