    quiet = modules_per_pixel * 4
    svg_total = total + quiet * 2

    lines = [
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {svg_total} {svg_total}" '
        f'width="250" height="250">',
        f'<rect width="{svg_total}" height="{svg_total}" fill="white"/>',
    ]

