                y = quiet + r * modules_per_pixel
                lines.append(
                    f'<rect x="{x}" y="{y}" width="{modules_per_pixel}" '
                    f'height="{modules_per_pixel}" fill="black"/>'
                )

    lines.append("</svg>")
    return "\n".join(lines)

