                    "id": cid[:12],
                    "name": details.get("Name", ""),
                    "image": details.get("Config", {}).get("Image", ""),
                    "privileged": True,
                    "capabilities": host_config.get("CapAdd", []),
                    "host_pid": host_config.get("PidMode", ""),
                    "mounts": [
