def ingest_all(self, lessons: list[LessonLearned] | None = None) -> int:
    """Ingest a batch of lessons.

    When *lessons* is ``None``, reads from the lessons JSONL file.

    Returns:
        Number of lessons successfully ingested.
    """
    if lessons is None:
        lessons = self._load_from_file()

    count = 0
    for lesson in lessons:
        if self.ingest(lesson):
            count += 1
    return count

def _load_from_file(self) -> list[LessonLearned]:
    """Load lessons from the JSONL file."""
    if not self._lessons_file.exists():
        return []
    lessons: list[LessonLearned] = []
    try:
        with self._lessons_file.open("r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    lessons.append(LessonLearned.from_dict(json.loads(line)))
                except Exception:
                    continue
    except Exception as exc:
        log.debug("LessonIngestor: file load failed: %s", exc)
    return lessons

def initialize_file_positions(self):
    """Set initial position to the end of all currently monitored files."""
    console.print("[yellow]Initializing file positions (reading to end)...[/yellow]")
    for root, _, files in os.walk(self.log_dir):
        for filename in files:
            file_path = os.path.join(root, filename)
            if self.is_monitored(file_path):
                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        f.seek(0, os.SEEK_END) # Ir al final del archivo
                        file_positions[file_path] = f.tell() # Guardar la posición final
                        logging.info(f"Initialized position for {file_path} at {file_positions[file_path]}")
                except Exception as e:
                    logging.error(f"Error initializing position for {file_path}: {e}")
