def _parse_escaped_hex(escaped: str) -> bytes:
    result = bytearray()
    for part in escaped.split("\\x"):
        if not part:
            continue
        try:
            result.append(int(part[:2], 16))
            for i in range(2, len(part), 2):
                if i + 2 <= len(part):
                    result.append(int(part[i:i + 2], 16))
        except ValueError:
            continue
    return bytes(result)

