def __init__(self) -> None:
    self._docs: list[dict[str, Any]] = []
    self._ids: set = set()    # for deduplication

def load(self, path: Path) -> None:
    """Load index from disk (no-op if file absent or corrupt)."""
    if not path.exists():
        return
    try:
        data = json.loads(path.read_text())
        self._docs = data.get("docs", [])
        self._ids  = {d["id"] for d in self._docs}
    except Exception:
        pass

def save(self, path: Path) -> None:
    """Atomically persist index to disk."""
    try:
        SESSIONS_DIR.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps({"docs": self._docs}, separators=(",", ":")))
        os.replace(tmp, path)
    except Exception:
        pass

def add(self, doc_id: str, text: str, meta: dict[str, Any]) -> None:
    if doc_id in self._ids:
        return  # deduplication
    self._docs.append({"id": doc_id, "text": text, "meta": meta})
    self._ids.add(doc_id)
    # Ring-buffer: discard oldest entries when cap is exceeded
    if len(self._docs) > MAX_FALLBACK_DOCS:
        evicted = self._docs.pop(0)
        self._ids.discard(evicted["id"])

def query(self, query_text: str, n: int = 5) -> list[dict[str, Any]]:
    words = set(query_text.lower().split())
    scored: list[tuple[int, dict[str, Any]]] = []
    for doc in self._docs:
        hits = sum(1 for w in words if w in doc["text"].lower())
        if hits:
            scored.append((hits, doc))
    scored.sort(key=lambda x: x[0], reverse=True)
    return [d for _, d in scored[:n]]

class _RagState:
    mtimes: dict[str, float] = field(default_factory=dict)

    @classmethod

def load(cls) -> _RagState:
    if RAG_STATE_FILE.exists():
        try:
            data = json.loads(RAG_STATE_FILE.read_text())
            return cls(mtimes=data.get("mtimes", {}))
        except Exception:
            pass
    return cls()

def _init_backend(self) -> None:
    if not _CHROMA_OK:
        log.info("session_rag: chromadb not installed — using keyword fallback")
        self._fallback.load(FALLBACK_INDEX_FILE)
        self._ready = True
        return
    try:
        CHROMA_DIR.mkdir(parents=True, exist_ok=True)
        current_version = chromadb.__version__
        stored_version = (
            CHROMA_VERSION_FILE.read_text().strip()
            if CHROMA_VERSION_FILE.exists()
            else None
        )
        if stored_version and stored_version != current_version:
            log.info(
                "session_rag: chromadb version changed (%s -> %s), "
                "clearing stale database",
                stored_version, current_version,
            )
            import shutil
            for item_path in CHROMA_DIR.iterdir():
                if item_path.is_file():
                    item_path.unlink()
                else:
                    shutil.rmtree(item_path)
        self._client = chromadb.PersistentClient(
            path=str(CHROMA_DIR),
        )
        for key, name in COLLECTIONS.items():
            try:
                self._collections[key] = self._client.get_collection(name)
            except Exception:
                self._collections[key] = self._client.create_collection(
                    name=name,
                    metadata={"hnsw:space": "cosine"},
                )
        CHROMA_VERSION_FILE.wri

def _iter_artefacts(self) -> list[Path]:
    files: list[Path] = []
    for p in SESSIONS_DIR.rglob("*"):
        if not p.is_file():
            continue
        if SKIP_PATTERNS.search(str(p)):
            continue
        if p.suffix.lower() not in INDEXABLE_SUFFIXES:
            continue
        if p.stat().st_size > 2_000_000:  # skip files > 2 MB
            continue
        files.append(p)
    return files

# ------------------------------------------------------------------
# Indexing
# ------------------------------------------------------------------

def _index_file(self, path: Path, collection_key: str = "sessions") -> int:
    """Index a single file; return number of chunks added."""
    try:
        text = path.read_text(errors="replace")
    except Exception:
        return 0
    if not text.strip():
        return 0

    rel = str(path.relative_to(SESSIONS_DIR))
    chunks = _chunk_text(text)
    added = 0
    col = self._collections.get(collection_key)
    for i, chunk in enumerate(chunks):
        doc_id = hashlib.md5(f"{rel}:{i}:{chunk[:40]}".encode()).hexdigest()
        meta = {
            "source":    rel,
            "chunk":     i,
            "mtime":     path.stat().st_mtime,
            "suffix":    path.suffix,
        }
        if col is not None:
            try:
                col.add(
                    documents=[chunk],
                    ids=[doc_id],
                    metadatas=[meta],
                )
                added += 1
            except Exception:
                pass  # duplicate id is fine
        else:
            self._fallback.add(doc_id, chunk, meta)
            added += 1
    return added

def index_new(self) -> dict[str, int]:
    """Incrementally index only new or changed files."""
    files = self._iter_artefacts()
    indexed_files = 0
    indexed_chunks = 0
    for path in files:
        rel = str(path.relative_to(SESSIONS_DIR))
        mtime = path.stat().st_mtime
        if self._state.mtimes.get(rel) == mtime:
            continue
        chunks = self._index_file(path)
        if chunks:
            indexed_files += 1
            indexed_chunks += chunks
            self._state.mtimes[rel] = mtime
    if indexed_files:
        self._state.save()
        if not self._collections:   # keyword fallback — persist to disk
            self._fallback.save(FALLBACK_INDEX_FILE)
    return {"files": indexed_files, "chunks": indexed_chunks}

def index_all(self) -> dict[str, int]:
    """Full re-index from scratch."""
    if self._client is not None:
        for key, name in COLLECTIONS.items():
            try:
                self._client.delete_collection(name)
                self._collections[key] = self._client.create_collection(
                    name=name,
                    metadata={"hnsw:space": "cosine"},
                )
            except Exception:
                pass
    else:
        self._fallback.reset()
        FALLBACK_INDEX_FILE.unlink(missing_ok=True)
    self._state = _RagState()

    r1 = self.index_new()
    r2 = self.index_parquet_sources(force=True)

    return {
        "files":  r1.get("files", 0) + r2.get("files", 0),
        "chunks": r1.get("chunks", 0) + r2.get("chunks", 0),
    }

# ------------------------------------------------------------------
# Query
# ------------------------------------------------------------------

def query(self, query_text: str, n: int = 5, collection: str = "all") -> list[dict[str, Any]]:
    """Return top-n relevant chunks as dicts with keys: text, source, chunk, score."""
    if self._collections:
        target_cols = []
        if collection == "all":
            target_cols = list(self._collections.values())
        elif collection in self._collections:
            target_cols = [self._collections[collection]]

        all_results = []
        for col in target_cols:
            try:
                count = col.count()
                if count == 0:
                    continue
                results = col.query(
                    query_texts=[query_text],
                    n_results=min(n, count),
                )
                docs      = results.get("documents", [[]])[0]
                metas     = results.get("metadatas", [[]])[0]
                distances = results.get("distances", [[]])[0]
                for doc, meta, dist in zip(docs, metas, distances, strict=False):
                    all_results.append({
                        "text":   doc,
                        "source": meta.get("source", ""),
                        "chunk":  meta.get("chunk", 0),
                        "score":  round(1.0 - dist, 4),
                    })
            except Exception as exc:
                log.debug("session_rag: ChromaDB query failed for collection (%s)", exc)

        # Sort all results by score and take top n

    def stats(self) -> dict[str, Any]:
        indexed = len(self._state.mtimes)
        if self._collections:
            total_chunks = sum(c.count() for c in self._collections.values())
            backend = "chromadb"
            col_stats = {k: c.count() for k, c in self._collections.items()}
        else:
            total_chunks = self._fallback.count()
            backend = "keyword_fallback"
            col_stats = {}
        return {
            "backend":       backend,
            "indexed_files": indexed,
            "total_chunks":  total_chunks,
            "collections":   col_stats,
            "chroma_ok":     _CHROMA_OK,
            "state_file":    str(RAG_STATE_FILE),
        }


