    if not EVENTS_FILE.exists():
        return []
    events = []
    try:
        for line in EVENTS_FILE.read_text().splitlines():
            line = line.strip()
            if line:
                try:
                    events.append(json.loads(line))
                except Exception:
                    pass
    except Exception:
