def register(self, technique: SleepTechnique) -> None:
    """Register a technique in the catalog."""
    self._techniques[technique.name] = technique

def get(self, name: str) -> SleepTechnique:
    """Retrieve a technique by name. Raises KeyError if missing."""
    if name not in self._techniques:
        available = ", ".join(sorted(self._techniques.keys()))
        raise KeyError(
            f"Sleep technique '{name}' not found. Available: {available}"
        )
    return self._techniques[name]

def list_all(self) -> list[SleepTechnique]:
    """Return all registered techniques sorted by detection resistance."""
    return sorted(
        self._techniques.values(),
        key=lambda t: t.detection_resistance,
        reverse=True,
    )

def list_by_platform(self, platform: OsPlatform) -> list[SleepTechnique]:
    """Return techniques supported on a given platform."""
    return [
        t for t in self._techniques.values()
        if platform in t.platforms
    ]

def list_names(self) -> list[str]:
    """Return sorted list of technique names."""
    return sorted(self._techniques.keys())

class SleepTechniqueValidator:
    """Validates a SleepObfuscationConfig against technique constraints."""

    @staticmethod

def validate(config: SleepObfuscationConfig, technique: SleepTechnique) -> list[str]:
    """Validate config against a technique definition.

    Returns a list of error strings (empty = valid).
    """
    errors: list[str] = []
    if config.rop_gadget_count < 1 and technique.requires_rop_gadgets:
        errors.append(
            f"Technique '{technique.name}' requires rop_gadget_count >= 1"
        )
    if config.rop_gadget_count > 20:
        errors.append(
            "rop_gadget_count > 20 is excessive and likely to cause instability"
        )
    if config.sleep_delay_ms < 0:
        errors.append("sleep_delay_ms must be >= 0")
    if config.sleep_delay_ms > 60000:
        errors.append("sleep_delay_ms > 60000 is excessive for sleep obfuscation")
    return errors

@staticmethod

def validate_config(config: SleepObfuscationConfig) -> list[str]:
    """Validate the config itself for internal consistency."""
    errors: list[str] = []
    if config.enabled and not config.technique_name:
        errors.append("technique_name is required when sleep obfuscation is enabled")
    return errors

def __init__(
    self,
    catalog: SleepTechniqueCatalog | None = None,
) -> None:
    self._catalog = catalog or _build_default_catalog()
    self._validator = SleepTechniqueValidator()
    self._config = SleepObfuscationConfig()

@property

def catalog(self) -> SleepTechniqueCatalog:
    """Return the technique catalog."""
    return self._catalog

@property

def config(self) -> SleepObfuscationConfig:
    """Return the active runtime configuration."""
    return self._config

@property

def detection_resistance(self) -> int:
    """Return the detection resistance score of the active technique.

    If the active technique is not found in the catalog (e.g., custom
    catalog was provided but config still references a built-in name),
    fall back to the highest available technique in the catalog.
    """
    try:
        tech = self._catalog.get(self._config.technique_name)
        return tech.detection_resistance
    except KeyError:
        techniques = self._catalog.list_all()
        if techniques:
            return max(t.detection_resistance for t in techniques)
        return 0

def select(self, technique_name: str) -> SleepTechnique:
    """Select a technique from the catalog.

    Returns the SleepTechnique. Raises KeyError if not found.
    """
    return self._catalog.get(technique_name)

def validate(self, config: SleepObfuscationConfig | None = None) -> list[str]:
    """Validate configuration against the active technique.

    Args:
        config: Optional config to validate. Uses self.config if None.

    Returns:
        List of error strings (empty = valid).
    """
    cfg = config or self._config
    try:
        technique = self._catalog.get(cfg.technique_name)
    except KeyError:
        return [f"Unknown technique: '{cfg.technique_name}'"]
    return self._validator.validate(cfg, technique)

def to_dict(self) -> dict[str, Any]:
    """Serialize the entire engine state to a dictionary."""
    return {
        "config": self._config.to_dict(),
        "available_techniques": self._catalog.list_names(),
        "active_detection_resistance": self.detection_resistance,
    }

@classmethod

    def message(self) -> str:
        """Return a human-readable message for this reply code."""
        messages = {
            0x00: "request granted",
            0x01: "general SOCKS server failure",
            0x02: "connection not allowed by ruleset",
            0x03: "network unreachable",
            0x04: "host unreachable",
            0x05: "connection refused",
            0x06: "TTL expired",
            0x07: "command not supported",
            0x08: "address type not supported",
        }
        return messages.get(self.value, f"unknown reply code {self.value}")


@dataclass

def validate_config(config: SocksProxyConfig) -> list[str]:
    """Validate a SocksProxyConfig and return error messages.

    Returns an empty list if the config is valid.
    """
    errors: list[str] = []

    try:
        ipaddress.ip_address(config.bind_address)
    except ValueError:
        errors.append(
            f"bind_address '{config.bind_address}' is not a valid IP address"
        )

    if not (SOCKS_MIN_PORT <= config.bind_port <= SOCKS_MAX_PORT):
        errors.append(
            f"bind_port {config.bind_port} is outside valid range "
            f"({SOCKS_MIN_PORT}-{SOCKS_MAX_PORT})"
        )

    if config.max_connections < 1:
        errors.append("max_connections must be >= 1")
    if config.max_connections > 65535:
        errors.append("max_connections must be <= 65535")

    if config.session_timeout_seconds < 5:
        errors.append("session_timeout_seconds must be >= 5")
    if config.session_timeout_seconds > 86400:
        errors.append("session_timeout_seconds must be <= 86400 (24 hours)")

    if config.bandwidth_limit_bps < 0:
        errors.append("bandwidth_limit_bps must be >= 0")

    has_userpass = SocksAuthMethod.USERNAME_PASSWORD in config.auth_methods
    if has_userpass and (not config.username or not config.password):
        errors.append(
            "username and password are required when USERNAME_PASSWORD "
            "authentication is enabled"
        )

def validate_request(
    command: int,
    address_type: int,
    host: str,
    port: int,
    config: SocksProxyConfig | None = None,
) -> tuple[bool, int, str]:
    """Validate a SOCKS5 request against the proxy configuration.

    Args:
        command: SOCKS command byte (CONNECT, BIND, UDP_ASSOCIATE).
        address_type: Address type byte (IPV4, DOMAIN, IPV6).
        host: Target hostname or IP address.
        port: Target port.
        config: Optional proxy config for access control checks.

    Returns:
        Tuple of (is_valid, reply_code, message).
    """
    if command not in (SocksCommand.CONNECT, SocksCommand.BIND, SocksCommand.UDP_ASSOCIATE):
        return False, SocksReply.COMMAND_NOT_SUPPORTED, "command not supported"

    if address_type not in (SocksAddressType.IPV4, SocksAddressType.DOMAIN, SocksAddressType.IPV6):
        return False, SocksReply.ADDRESS_TYPE_NOT_SUPPORTED, "address type not supported"

    if not host:
        return False, SocksReply.GENERAL_FAILURE, "host is required"

    if len(host) > SOCKS_MAX_ADDR_LEN:
        return False, SocksReply.GENERAL_FAILURE, f"host exceeds {SOCKS_MAX_ADDR_LEN} characters"

    if not (SOCKS_MIN_PORT <= port <= SOCKS_MAX_PORT):
        return False, SocksReply.GENERAL_FAILURE, f"port {port} is invalid"

    if config is not None:
        return SocksValidator._check_access_control(host, port, config)

    return True, SocksReply.SUCCEEDED, "request valid"

@staticmethod

def _check_access_control(
    host: str,
    port: int,
    config: SocksProxyConfig,
) -> tuple[bool, int, str]:
    """Apply access control rules from proxy config."""
    if config.denied_ports and port in config.denied_ports:
        return False, SocksReply.CONNECTION_NOT_ALLOWED, f"port {port} is denied"
    if config.allowed_ports and port not in config.allowed_ports:
        return False, SocksReply.CONNECTION_NOT_ALLOWED, f"port {port} is not in allowed list"

    try:
        ip = ipaddress.ip_address(host)
    except ValueError:
        try:
            ip = socket.getaddrinfo(host, None)[0][4][0]
            ip = ipaddress.ip_address(ip)
        except (socket.gaierror, OSError, IndexError):
            return True, SocksReply.SUCCEEDED, "hostname resolution deferred"

    if ip.is_loopback and not config.allow_localhost:
        return False, SocksReply.CONNECTION_NOT_ALLOWED, "localhost connections not allowed"
    if ip.is_private and not config.allow_private_ranges:
        return False, SocksReply.CONNECTION_NOT_ALLOWED, "private range connections not allowed"

    return True, SocksReply.SUCCEEDED, "access granted"

def __init__(self, config: SocksProxyConfig | None = None) -> None:
