def _extract_method_source(source: str, method_name: str) -> str | None:
    """Extract the source block for *method_name* from Python source string."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == method_name:
            lines = source.splitlines()
            block = "\n".join(lines[node.lineno - 1 : node.end_lineno])
            return block
    return None

def _method_names_from_file(filepath: str) -> set[str]:
    """Return the set of ``do_*`` method names defined in *filepath*."""
    if not os.path.isfile(filepath):
        return set()
    with open(filepath, encoding="utf-8") as fh:
        source = fh.read()
    names: set[str] = set()
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return names
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name.startswith("do_"):
            names.add(node.name)
    return names

def _find_class_end(source_lines: list[str]) -> int:
    """Return the zero-based line index of the last line inside the module-level class."""
    for i, line in enumerate(source_lines):
        if line.startswith("class "):
            indent = len(line) - len(line.lstrip())
            for j in range(i + 1, len(source_lines)):
                stripped = source_lines[j].strip()
                current_indent = len(source_lines[j]) - len(source_lines[j].lstrip())
                if stripped and current_indent <= indent:
                    return j
            return len(source_lines) - 1
    return len(source_lines)

def merge_phase(phase: str, dry_run: bool = False) -> bool:
    """Merge one phase's migrated methods into its clean file. Returns True if changed."""
    migrated_filename = _PHASE_MIGRATED.get(phase)
    if not migrated_filename:
        print(f"[SKIP] unknown phase: {phase}")
        return False
    migrated_path = os.path.join(CLI_COMMANDS_DIR, migrated_filename)
    clean_path = os.path.join(CLI_COMMANDS_DIR, f"{phase}.py")
    if not os.path.isfile(migrated_path):
        print(f"[SKIP] {migrated_filename} not found")
        return False
    if not os.path.isfile(clean_path):
        print(f"[SKIP] {phase}.py not found")
        return False

    existing = _method_names_from_file(clean_path)
    with open(migrated_path, encoding="utf-8") as fh:
        source = fh.read()

    migrated = {n for n in _method_names_from_file(migrated_path) if n.startswith("do_")}
    missing = migrated - existing
    if not missing:
        print(f"[OK] {phase}: all {len(migrated)} methods already in {phase}.py")
        return False

    print(f"[MERGE] {phase}: {len(existing)} in clean, {len(migrated)} in migrated, {len(missing)} missing")

    methods: dict[str, str] = {}
    for name in sorted(missing):
        block = _extract_method_source(source, name)
        if block:
            methods[name] = block

    if dry_run:
        print(f"  Would add: {', '.join(sorted(methods.keys()))}")
        return bool(methods)

    changed, count = _append_methods(clean_path, methods)
    return changed

def _category_from_decorator(decorator: ast.expr) -> str | None:
    """Return the category name from a ``with_category(...)`` decorator."""
    if isinstance(decorator, ast.Call):
        fn = decorator.func
        if isinstance(fn, ast.Attribute) and fn.attr == "with_category":
            if decorator.args:
                arg = decorator.args[0]
                if isinstance(arg, ast.Name):
                    return arg.id
                elif isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                    return repr(arg.value)
    return None

def extract_method(source: str, node: ast.FunctionDef) -> str:
    """Return the raw source text of a function definition."""
    start_line = node.lineno - 1
    end_line = node.end_lineno
    lines = source.splitlines()[start_line:end_line]
    return "\n".join(lines)

def rewrite_globals(method_source: str) -> str:
    """Replace bare module-global names with ``self.params[...]``.

    Uses a two-pass approach: first mask existing ``self.params["X"]``
    calls with placeholders so the bare-variable regex does not double-
    wrap string values, then restore the placeholders.
    """
    markers: dict[str, str] = {}
    for var in MODULE_GLOBALS:
        marker = f"__GLOBAL_MARKER_{var.upper()}__"
        for quote in ('"', "'"):
            markers[f"self.params[{quote}{var}{quote}]"] = marker
            markers[f"self.params.get({quote}{var}{quote}"] = marker
            markers[f"self.params.get({quote}{var}{quote},"] = marker

    for old, new in markers.items():
        method_source = method_source.replace(old, new)

    for var in MODULE_GLOBALS:
        pattern = rf"(?<!\w)\b{re.escape(var)}\b(?!\s*=)"
        method_source = re.sub(pattern, rf'self.params["{var}"]', method_source)

    for old, new in markers.items():
        method_source = method_source.replace(new, old)

    return method_source

def main() -> int:
    if not LAZYOWN_PATH.exists():
        print(f"ERROR: {LAZYOWN_PATH} not found")
        return 1

    source = LAZYOWN_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)

    methods_by_category: dict[str, list[tuple[str, str]]] = {}
    methods_using_globals: list[str] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.FunctionDef):
            continue
        if not node.name.startswith("do_"):
            continue

        category = None
        for dec in node.decorator_list:
            category = _category_from_decorator(dec)
            if category:
                break

        if category is None:
            category = "miscellaneous_category"

        raw = extract_method(source, node)

        # Detect globals usage
        uses_globals = False
        for child in ast.walk(node):
            if isinstance(child, ast.Name) and child.id in MODULE_GLOBALS:
                uses_globals = True
                break

        if uses_globals:
            methods_using_globals.append(node.name)
            raw = rewrite_globals(raw)

        methods_by_category.setdefault(category, []).append((node.name, raw))

