def main(argv: list[str] | None = None) -> int:
    """Run the orchestrator CLI and return the process exit code."""
    parser = _build_parser()
    args = parser.parse_args(argv)
    config = load_config()
    if args.claude_md:
        config.claude_md_path = Path(args.claude_md).expanduser().resolve()
    if args.run_dir:
        config.run_dir = Path(args.run_dir).expanduser().resolve()
    if not args.strict:
        config.reviewer_strict = False
    options = {
        "auto_commit": args.auto_commit,
        "deploy_token": args.deploy_token,
        "seeds": [
            {"contract_id": seed, "title": seed, "rationale": "seeded contract"}
            for seed in args.seed
        ],
    }
    if args.no_parse:
        config.claude_md_path = Path("/dev/null")
        if not options["seeds"] and not args.contract_file:
            raise SystemExit("--no-parse requires --seed or --contract-file")
        for path_str in args.contract_file:
            path = Path(path_str).expanduser().resolve()
            if not path.exists():
                continue
            for contract in parser_mod.parse_claude_md(path):
                options["seeds"].append(
                    {
                        "contract_id": contract.contract_id,
                        "title": contract.title,
                        "rationale": contract.rationale,
                    }
                )
    summary = run(config, options)
    _print_summary(summary)
    if summary.halted_at is not None:
        return 2
    return 0

def __post_init__(self) -> None:
    if self.children is None:
        self.children = []

def flush_body() -> None:
    text = "\n".join(current_body).strip()
    if text and stack[-1].body != text:
        if stack[-1].body:
            stack[-1].body = stack[-1].body + "\n\n" + text
        else:
            stack[-1].body = text
    current_body.clear()

for line in lines:
    match = CONTRACT_HEADING_PATTERN.match(line)
    if match:
        flush_body()
        depth = len(match.group("hashes"))
        title = match.group("title").strip()
        node = _Section(depth=depth, title=title)
        while stack and stack[-1].depth >= depth:
            stack.pop()
        stack[-1].children.append(node)
        stack.append(node)
        continue
    current_body.append(line)
flush_body()
return root.children

def _collect_paragraphs(text: str) -> list[str]:
    """Return the paragraphs inside a section body."""
    return [p.strip() for p in re.split(r"\n\s*\n", text) if p.strip()]

def _is_actionable(heading: _Section) -> bool:
    """Return True when a section qualifies as a contract.

    The parser treats a section as a contract when the heading carries
    the CONTRACT keyword or the body declares an explicit outcomes
    list. The marker is case insensitive.
    """
    if CONTRACT_TAG_PATTERN.search(heading.title):
        return True
    body = heading.body.lower()
    return ("out of scope" in body and "happy path" in body) or (
        "trigger" in body and "sad path" in body
    )

def _flatten_actionable(root: _Section) -> Iterable[_Section]:
    """Yield every actionable section in depth first order."""
    for child in root.children:
        yield from _flatten_actionable(child)
        if _is_actionable(child):
            yield child

