def combined(self) -> str:
    """Return stdout and stderr combined."""
    parts = [self.stdout]
    if self.stderr:
        parts.append(f"[stderr]\n{self.stderr}")
    return "\n".join(parts)

@property

def success(self) -> bool:
    """Return True if the command exited cleanly and did not time out."""
    return not self.timed_out and (self.returncode == 0 or self.returncode is None)

def __str__(self) -> str:
    status = "OK" if self.success else f"FAIL({self.returncode})"
    if self.timed_out:
        status = "TIMEOUT"
    return f"[{status} {self.duration_ms:.0f}ms] {self.stdout[:200]}"

def _run_via_subprocess(self, command: str, timeout: int) -> ExecutionResult:
    """Execute via subprocess.Popen with PTY when available."""
    import time as time_module

    start = time_module.time()

    argv = [sys.executable, "-W", "ignore", str(self._lazyown_py)]
    env = os.environ.copy()
    env["TERM"] = "dumb"

    use_pty = self._has_pty()

    try:
        if use_pty:
            result = self._run_with_pty(argv, command, timeout, env)
        else:
            result = self._run_without_pty(argv, command, timeout, env)
    except Exception as exc:
        duration = (time_module.time() - start) * 1000
        return ExecutionResult(
            stdout="",
            stderr=f"Execution error: {exc}",
            returncode=-1,
            duration_ms=duration,
        )

    duration = (time_module.time() - start) * 1000
    return ExecutionResult(
        stdout=result.get("stdout", ""),
        stderr=result.get("stderr", ""),
        returncode=result.get("returncode"),
        timed_out=result.get("timed_out", False),
        duration_ms=duration,
    )

def _run_without_pty(
    self, argv: list[str], command: str, timeout: int, env: dict[str, str]
) -> dict[str, Any]:
    """Run without PTY (fallback for constrained environments)."""
    proc = subprocess.Popen(
        argv,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        cwd=str(self._lazyown_dir),
        env=env,
    )
    try:
        stdout_b, stderr_b = proc.communicate(command.encode(), timeout=timeout)
        return {
            "stdout": stdout_b.decode(errors="replace").strip(),
            "stderr": stderr_b.decode(errors="replace").strip(),
            "returncode": proc.returncode,
            "timed_out": False,
        }
    except subprocess.TimeoutExpired:
        proc.kill()
        stdout_b, stderr_b = proc.communicate()
        return {
            "stdout": stdout_b.decode(errors="replace").strip(),
            "stderr": stderr_b.decode(errors="replace").strip(),
            "returncode": proc.returncode,
            "timed_out": True,
        }

def _has_pty(self) -> bool:
    """Return True if the platform supports PTY subprocesses."""
    try:
        import pty as _pty_test  # noqa: F401
        return True
    except ImportError:
        return False

class HermesSyncError(Exception):
    """Raised when a sync operation cannot complete."""

    pass

def __init__(self, sessions_dir: Path | None = None) -> None:
    self._sessions_dir = sessions_dir or Paths.sessions_dir()
    self._checkpoint_file = self._sessions_dir / "hermes_checkpoint.json"

def write(self, state: dict[str, Any]) -> None:
    """Write a checkpoint to disk."""
    payload = {
        "version": Defaults.CHECKPOINT_VERSION,
        "timestamp": time.time(),
        "state": state,
    }
    try:
        self._checkpoint_file.write_text(
            json.dumps(payload, indent=2, default=str), encoding="utf-8"
        )
    except OSError as exc:
        raise HermesSyncError(f"Failed to write checkpoint: {exc}") from exc

def read(self) -> dict[str, Any] | None:
    """Read the latest checkpoint, or None if absent / stale."""
    try:
        if not self._checkpoint_file.exists():
            return None
        data = json.loads(self._checkpoint_file.read_text(encoding="utf-8"))
        if data.get("version") != Defaults.CHECKPOINT_VERSION:
            return None
        ts = data.get("timestamp", 0)
        if time.time() - ts > Defaults.FRESHNESS_THRESHOLD_SECONDS:
            return None
        return data.get("state")
    except (json.JSONDecodeError, OSError):
        return None

def clear(self) -> None:
    """Remove the checkpoint file."""
    try:
        if self._checkpoint_file.exists():
            self._checkpoint_file.unlink()
    except OSError:
        pass

def pending_objectives(self) -> list[dict[str, Any]]:
    """Return all pending objectives from objectives.jsonl."""
    objectives: list[dict[str, Any]] = []
    if not self._objectives_path.exists():
        return objectives
    try:
        with self._objectives_path.open("r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if obj.get("status") in (None, "pending", "new"):
                    objectives.append(obj)
    except OSError:
        pass
    return objectives

