        skills_dir = str(Paths.lazyown_dir() / "skills")
        modules_dir = str(Paths.lazyown_dir() / "modules")
        for d in (lazyown_dir, skills_dir, modules_dir):
            if d not in sys.path:
                sys.path.insert(0, d)
        return __import__(module_name, fromlist=[""])
    except Exception:
        return None


