        for d in decisions[:5]:
            lines.append(
                f"[{d.action:16s}] priority={d.priority}  "
                f"cmd={d.command}  ({d.reason})"
            )
        return "\n".join(lines)
    except Exception as exc:
        return f"[reactive_suggest error] {exc}"

