def resolution_for(self, approval_id: str) -> ApprovalOutcome | None:
    if not self._path.exists():
        return None
    try:
        latest: dict | None = None
        for line in self._path.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            try:
                rec = json.loads(line)
            except Exception:
                continue
            if rec.get("approval_id") != approval_id:
                continue
            status = rec.get("status", "pending")
            if status in ("approved", "denied"):
                latest = rec
        if latest is None:
            return None
        return ApprovalOutcome(
            decision=ApprovalDecision(latest["status"]),
            approval_id=approval_id,
            rationale=str(latest.get("rationale", "operator decision")),
            operator=str(latest.get("operator", "")),
        )
    except Exception:
        return None

