@staticmethod

def _extract_method_body(src: str, name: str) -> str:
    pattern = re.compile(
        rf"^(\s*)def {re.escape(name)}\(.*?\):\n(.*?)(?=^\1(?:def |@cmd2|@with_)|^class )",
        re.MULTILINE | re.DOTALL,
    )
    match = pattern.search(src)
    if match is None:
        return ""
    return match.group(2)

