def _run_ruff(args: list[str]) -> subprocess.CompletedProcess[str]:
    """Invoke ``python -m ruff`` so the venv's ruff binary is always used."""
    return subprocess.run(
        [sys.executable, "-m", "ruff", *args],
        capture_output=True,
        text=True,
        cwd=str(REPO_ROOT),
        timeout=120,
    )


