        data = yaml.safe_load(path.read_text())
        if not isinstance(data, dict):
            continue
        for param in data.get("params") or []:
            if (
                param.get("required")
                and "default" not in param
                and param["name"] not in live
            ):
                offenders.append(f"{path.name}:{{{param['name']}}}")
    assert offenders == []

