def _would_run(template: str, domain: str) -> bool:
    """Mirror pwntomate's skip rules: empty domain / leftover placeholder."""
    if "{domain}" in template and not domain:
        return False
    if _UNRESOLVED_RE.search(_render(template, domain, "")):
        return False
    return True

