def _load_prompt_payload() -> dict:
    """Read ``payload.json`` defensively for the prompt renderer.

    The prompt is rendered before the shell finishes wiring its parameters,
    so direct attribute access on the shell would race. Reading the file
    each time keeps the prompt in sync with operator-driven updates without
    coupling the renderer to the shell's lifecycle.
    """
    try:
        return load_payload(PAYLOAD_FILENAME)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return {}

def teclado_usuario(filename):
    """
    Processes a file to extract and display characters from specific write sequences.

    Args:
        filename (str): El nombre del archivo a leer.

    Raises:
        FileNotFoundError: Si el archivo no se encuentra.
        Exception: Para otros errores que puedan ocurrir.
    """
    try:
        with open(filename, 'r') as file:
            content = file.readlines()

        output = ""
        for line in content:
            if line.startswith('write(5,'):
                match = re.search(r'write\(5, "(.*?)"', line)
                if match:
                    char = match.group(1)
                    if char in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -.':
                        output += char
                    elif char == '\\n':
                        print(output)
                        output = ""

        if output:  # Imprimir cualquier salida restante
            print(output)

    except FileNotFoundError:
        print(f"Archivo {filename} no encontrado.")
    except Exception as e:
        print(f"Error: {e}")

